def unit_of_work(metadata=None, timeout=None):
    """
    This function is a decorator for transaction functions that allows extra control over how the transaction
    is carried out.

    Example usage::

        @unit_of_work(timeout=100)
        def count_people_tx(tx):
            result = tx.run("MATCH (a:Person) RETURN count(a) AS persons")
            record = result.single()
            return record["persons"]
    """
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            # Attach metadata if supported
            if hasattr(tx, 'metadata') and isinstance(tx.metadata, dict):
                if metadata:
                    tx.metadata.update(metadata)
            # Set timeout if supported
            if timeout is not None and hasattr(tx, 'timeout'):
                tx.timeout = timeout
            return func(tx, *args, **kwargs)
        return wrapper
    return decorator

