    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        counter = 0

        def make_key(args, kwargs):
            if typed:
                args_key = args + tuple(type(arg) for arg in args)
                kwargs_key = tuple((k, kwargs[k], type(kwargs[k])) for k in sorted(kwargs))
                return args_key + kwargs_key
            else:
                return args + tuple(sorted(kwargs.items()))

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal counter
            key = make_key(args, kwargs)
            if key in cache:
                value, freq, _ = cache[key]
                freq += 1
                counter += 1
                cache[key] = (value, freq, counter)
                return value

            value = func(*args, **kwargs)
            counter += 1
            cache[key] = (value, 1, counter)

            if maxsize is not None and len(cache) > maxsize:
                min_freq = min(v[1] for v in cache.values())
                candidates = [k for k, v in cache.items() if v[1] == min_freq]
                if len(candidates) > 1:
                    min_key = min(candidates, key=lambda k: cache[k][2])
                else:
                    min_key = candidates[0]
                del cache[min_key]

            return value

        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        freq = {}

        def make_key(args, kwargs):
            if typed:
                key_args = tuple((type(arg), arg) for arg in args)
                key_kwargs = tuple((k, type(v), v) for k, v in sorted(kwargs.items()))
                return (key_args, key_kwargs)
            else:
                return (args, tuple(sorted(kwargs.items())))

        @wraps(func)
        def wrapper(*args, **kwargs):
            k = make_key(args, kwargs)
            if k in cache:
                val, f = cache[k]
                f += 1
                cache[k] = (val, f)
                freq[k] = f
                return val

            val = func(*args, **kwargs)

            if maxsize and len(cache) >= maxsize:
                min_f = min(freq.values())
                # Evict one of the keys with the minimum frequency
                evict_key = next(k for k, f in freq.items() if f == min_f)
                cache.pop(evict_key, None)
                freq.pop(evict_key, None)

            cache[k] = (val, 1)
            freq[k] = 1
            return val

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if maxsize < 0:
        raise ValueError("maxsize must be non-negative")
    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            items = tuple(sorted(kwargs.items()))
            key = key + items
        if typed:
            key = key + tuple(type(v) for v in args) + tuple(type(v) for v in kwargs.values())
        return key
    def decorator(fn):
        cache = {}
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                value, freq = cache[key]
                cache[key] = (value, freq + 1)
                return value
            value = fn(*args, **kwargs)
            if maxsize > 0 and len(cache) >= maxsize:
                # find key with lowest frequency, evict one
                min_freq = min(freq for _, freq in cache.values())
                # Evict the first key that matches the min frequency
                for evict_key, (_, freq) in cache.items():
                    if freq == min_freq:
                        del cache[evict_key]
                        break
            cache[key] = (value, 1)
            return value
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        freq = {}
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                key = args + tuple(kwargs.items()) + tuple(type(a) for a in args) + tuple(type(v) for _, v in sorted(kwargs.items()))
            else:
                key = args + tuple(kwargs.items())
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            if maxsize > 0 and len(cache) >= maxsize:
                min_freq = min(freq.values())
                # Find the first key with the minimum frequency (in insertion order)
                evict_key = next(k for k, v in freq.items() if v == min_freq)
                del cache[evict_key]
                del freq[evict_key]
            cache[key] = result
            freq[key] = 1
            return result
        return wrapper
    return decorator

