def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Preserve original order while removing duplicates
    seen = set()
    unique_bases = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique_bases.append(cls)

    # Build the minimal set: keep a class only if no other base in the list
    # is a subclass of it (i.e., it is not a superclass of any other).
    minimal = []
    for cls in unique_bases:
        if not any(
            cls is not sub and issubclass(sub, cls)
            for sub in unique_bases
        ):
            minimal.append(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    kept = []
    for cls in classes:
        # If the current class is already a subclass of a class in the result,
        # it is redundant and can be skipped.
        if any(issubclass(cls, kept_cls) for kept_cls in kept):
            continue
        # Remove any already kept classes that are subclasses of the new one.
        kept = [c for c in kept if not issubclass(c, cls)]
        kept.append(cls)
    return tuple(kept)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # If no classes or empty list, return as is
    if not classes:
        return []

    # Determine which classes are needed: keep a class if no other class in the list
    # is a subclass of it (other than itself). This removes redundant superclasses.
    minimal = []
    for cls in classes:
        # Check that there is no other distinct class that is a subclass of cls
        if not any(other is not cls and issubclass(other, cls) for other in classes):
            minimal.append(cls)
    return minimal

def minimalBases(classes):
