    seen = []
    for cls in classes:
        # Skip if `cls` is a superclass of any other class in the list
        if any(other is not cls and issubclass(other, cls) for other in classes):
            continue
        seen.append(cls)
    return seen

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    result = {}
    # Determine which classes to inspect
    classes = (self,) if not all else (self,) + self.__bases__
    for cls in classes:
        for name, obj in cls.__dict__.items():
            # Skip private or special attributes
            if name.startswith('_'):
                continue
            # Many interface attributes are descriptor objects that
            # have a `description` attribute (e.g., zope.interface.Attribute).
            if hasattr(obj, 'description'):
                result[name] = obj.description
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Determine the attribute collection strategy.
    # Prefer an explicit interface definition if present.
    cls = self.__class__
    attrs = {}
    iface = getattr(cls, '__interface__', None)
    if iface and hasattr(iface, 'attributes'):
        # zope.interface style: attributes is a mapping of name -> Attribute
        for name, attr in iface.attributes.items():
            # attr is a zope.interface.Attribute with .description
            desc = getattr(attr, 'description', None)
            if desc is None:
                desc = ''
            attrs[name] = desc
    else:
        # Fallback: inspect class dictionary for non-callable, non-private members.
        # If 'all' is True, walk the MRO to gather attributes from base classes.
        mro = cls.__mro__ if all else (cls,)
        for base in mro:
            for name, val in base.__dict__.items():
                if name.startswith('_'):
                    continue
                if callable(val):
                    continue
                # Attempt to obtain a description: use docstring if available.
                desc = None
                # For property objects, the docstring lives on the fget function.
                if isinstance(val, property):
                    fget = getattr(val, 'fget', None)
                    desc = fget.__doc__ if fget else None
                if desc is None:
                    desc = getattr(val, '__doc__', None)
                if desc is None:
                    desc = ''
                attrs[name] = desc
    # Return sorted list of (name, description) tuples.
    return [(name, attrs[name]) for name in sorted(attrs)]

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    # Iterate over attributes defined directly on the class of this instance.
    for name, member in getattr(self, "__class__").__dict__.items():
        # Skip private attributes unless `all` is True.
        if not all and name.startswith("_"):
            continue

        # Skip methods or any callable objects.
        if callable(member):
            continue

        # Attempt to retrieve a description (docstring) for the member.
        desc = None
        if isinstance(member, (property, staticmethod, classmethod)):
            # For descriptors, get the underlying function's docstring.
            func = getattr(member, "__func__", None) or getattr(member, "fget", None)
            desc = getattr(func, "__doc__", None) if func else None
        else:
            # For plain attributes, use the `__doc__` attribute if present.
            desc = getattr(member, "__doc__", None)

        result[name] = desc
    return result

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    # Determine classes to inspect: all base classes if requested
    classes = [self.__class__]
    if all:
        classes = self.__class__.__mro__
    for cls in classes:
        for name, value in vars(cls).items():
            # Skip private/special attributes and methods
            if name.startswith('_') or callable(value):
                continue
            # Extract a description if possible
            description = ''
            if isinstance(value, property):
                fget = value.fget
                description = fget.__doc__ or ''
            else:
                description = getattr(value, '__doc__', '') or ''
            result[name] = description
    return result

def namesAndDescriptions(self, all=False):
        """Return attribute names and descriptions defined by interface."""
        cls = self.__class__
        if all:
            names = dir(cls)
        else:
            names = list(cls.__dict__.keys())
        result = []
        for name in names:
            if not all and name.startswith('_'):
                continue
            try:
                obj = getattr(cls, name)
                doc = getattr(obj, "__doc__", "")
                if doc is None:
                    doc = ""
            except Exception:
                doc = ""
            result.append((name, doc))
        return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect attribute names from the class and its bases, excluding private
    # and internal members, and optionally including callables.
    attribute_names = set()
    for cls in self.__class__.__mro__:
        for name, value in cls.__dict__.items():
            if name.startswith('_'):
                # Skip private and special attributes
                continue
            is_callable = callable(value)
            if all or not is_callable:
                attribute_names.add(name)
    # Return a sorted list for consistent ordering
    return sorted(attribute_names)

