def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    # If the environment variable is set, do not use C optimizations
    if os.getenv('PURE_PYTHON'):
        return False

    # PyPy often cannot use compiled C extensions reliably
    if hasattr(sys, 'pypy_version_info'):
        return False

    # Delegate to the _use_c_impl function if it exists
    try:
        from . import _use_c_impl
        return _use_c_impl()
    except Exception:
        # Fall back to using C optimizations if we cannot determine otherwise
        return True

