def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    import numpy as np
    errors = getattr(self, 'errors', {})
    err_arr = errors.get(coord_name)
    if err_arr is None:
        return []
    err_arr = np.asarray(err_arr)
    mask = np.isfinite(err_arr) & (err_arr != 0)
    return np.where(mask)[0].tolist()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # The errors attribute is expected to be a mapping from coordinate names
    # to error data (scalars, lists, arrays, etc.).  This helper returns a
    # list of integer indices that can be used to index into any error vector
    # that contains all coordinate errors in sequence.
    if not hasattr(self, "errors"):
        raise AttributeError("The object does not contain an 'errors' attribute.")
    # Resolve the error entry for the coordinate
    if isinstance(self.errors, dict):
        err_entry = self.errors.get(coord_name, None)
    else:
        # If errors is not a dict, treat it as a sequence of (name, value) pairs
        err_entry = None
        for key, value in self.errors:
            if key == coord_name:
                err_entry = value
                break
    if err_entry is None:
        # No error information for this coordinate
        return []
    # If the entry is a sequence, return indices over its length.
    # For scalar entries we simply return index 0.
    try:
        length = len(err_entry)
    except Exception:
        return [0]
    return list(range(length))

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not hasattr(self, "_err_indices"):
        raise AttributeError(
            "Instance does not contain error indices information."
        )
    if coord_name not in self._err_indices:
        raise KeyError(
            f"Coordinate {coord_name!r} not found in {self.__class__.__name__}._err_indices"
        )
    return self._err_indices[coord_name]

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Look for a dedicated error dictionary on the instance.
    errors = getattr(self, 'errors', None)
    if isinstance(errors, dict):
        err_arr = errors.get(coord_name)
        if err_arr is not None:
            # If the error array can provide indices directly.
            if hasattr(err_arr, 'nonzero'):
                return err_arr.nonzero()[0]
            # If the array is a NumPy array or sequence, return all indices.
            try:
                return np.arange(len(err_arr))
            except Exception:
                return np.array([], dtype=int)

    # Fall back to searching in the variable store.
    var_store = getattr(self, '_variables', {})
    err_var_name = f"{coord_name}_err"
    err_var = var_store.get(err_var_name)
    if err_var is not None:
        if hasattr(err_var, 'nonzero'):
            return err_var.nonzero()[0]
        try:
            return np.arange(len(err_var))
        except Exception:
            return np.array([], dtype=int)

    # If no error data is found, return an empty array.
    return np.array([], dtype=int)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve stored error indices for the given coordinate name.
    # If none are available return an empty list.
    return self._err_indices.get(coord_name, [])

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Ensure the context has an 'error' subcontext
    if not hasattr(context, 'error'):
        context.error = SimpleNamespace()

    # Get the graph's error mapping.  Prefer a dictionary `self.errors`,
    # otherwise try to interpret iterable of (field, index) pairs.
    try:
        errors = dict(self.errors)
    except AttributeError:
        try:
            errors = dict(self._errors)
        except AttributeError:
            errors = {}
    except TypeError:
        # self.errors may be an iterable of tuples
        try:
            errors = dict(self.errors)
        except Exception:
            errors = {}

    # Build a mapping from coordinate names to axis letters.
    # We assume the graph exposes a list of column/field names in
    # `self.fields`, `self.columns`, or `self._fields`.  Only the first
    # three are considered for axis mapping.
    colnames = getattr(self, 'fields', None)
    if colnames is None:
        colnames = getattr(self, 'columns', None)
    if colnames is None:
        colnames = getattr(self, '_fields', None)
    if not isinstance(colnames, (list, tuple)):
        colnames = []

    axis_map = {}
    for idx, name in enumerate(colnames[:3]):
        if idx == 0:
            axis_map[name] = 'x'
        elif idx == 1:
            axis_map[name] = 'y'
        elif idx == 2:
            axis_map[name] = 'z'

    # Process each error entry
    for field, index in errors.items():
        # Expect error field names in the form 'error_<base>_<suffix>'
        if not isinstance(field, str):
            continue
        if not field.startswith('error_'):
            continue

        # Strip the 'error_' prefix
        rem = field[6:]
        # Split into base coordinate name and the suffix
        parts = rem.split('_', 1)
        if len(parts) != 2:
            # If there is no suffix, skip
            continue
        base_name, suffix = parts
        axis_letter = axis_map.get(base_name)
        if not axis_letter:
            # If the base name is not one of the first three columns,
            # skip this error
            continue
        error_label = f'{axis_letter}_{suffix}'

        # Attach error info into the context's error subcontext
        setattr(context.error, error_label, SimpleNamespace(index=index))
    # No modification to context.value; existing data is preserved.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    bins = np.asarray(bins)
    edges = np.asarray(edges)

    if bins.ndim != 1 or edges.ndim != 1:
        raise ValueError("bins and edges must be one-dimensional arrays")

    if len(edges) != len(bins) + 1:
        raise ValueError("edges must contain one more element than bins")

    return np.sum(bins * np.diff(edges))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq is already a single FillRequest instance, it is valid.
    if isinstance(seq, FillRequest):
        return True

    # A Source sequence should not be considered a FillRequestSeq.
    if isinstance(seq, Source):
        return False

    # Try to iterate over seq; if it is not iterable, it cannot be a sequence.
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    # Strings (and bytes) are technically iterable but should not be
    # treated as sequences for this purpose.
    if isinstance(seq, (str, bytes)):
        return False

    # Check if at least one element of the sequence is a FillRequest.
    for element in iterator:
        if isinstance(element, FillRequest):
            return True

    return False

