            # key only in d1
            diff[key] = val1
        else:
            val2 = d2[key]
            # Determine if we should recurse
            if isinstance(val1, dict) and isinstance(val2, dict) and level != 0:
                # Compute bounds for recursion depth
                new_level = level - 1 if level > 0 else -1
                subdiff = difference(val1, val2, new_level)
                if subdiff:
                    diff[key] = subdiff
            else:
                # Compare values directly
                if val1 != val2:
                    diff[key] = val1
    return diff

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    def _diff_rec(d1, d2, lvl):
        result = {}
        for key, v in d1.items():
            if key not in d2:
                # key missing in d2, include whole value
                result[key] = v
            else:
                v2 = d2[key]
                if isinstance(v, dict) and isinstance(v2, dict):
                    # recurse if depth allows
                    if lvl != 0:
                        sublvl = lvl - 1 if lvl > 0 else -1
                        subdiff = _diff_rec(v, v2, sublvl)
                        if subdiff:
                            result[key] = subdiff
                else:
                    # non-dict values: include if different
                    if v != v2:
                        result[key] = v
        return result

    return _diff_rec(d1, d2, level)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion.  For infinite recursion,
    *level* can be set to -1.  For level 1, if a key is present both in
    *d1* and *d2* but has different values, it is included in the difference.
    For nested dictionaries, recursion goes up to *level* depth.
    """
    # Helper to compute next recursion depth
    def _next_depth(cur):
        return cur - 1 if cur > 0 else cur

    diff = {}
    for k, v in d1.items():
        if k not in d2:
            # key missing in d2: include the whole entry
            diff[k] = v
            continue

        # key exists in both
        v2 = d2[k]
        if isinstance(v, dict) and isinstance(v2, dict):
            # both are dicts: recurse if depth allows
            if level == 0:
                # depth reached, treat as differing dict
                diff[k] = v
            else:
                sub = difference(v, v2, _next_depth(level))
                if sub:
                    diff[k] = sub
        else:
            # non-dict comparison
            if v != v2:
                diff[k] = v
    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Convert coordinate to a NumPy array
    coord = np.asarray(coord)

    # Support a single point or multiple points
    if coord.ndim == 1:
        dims = len(self.edges)
        if len(coord) != dims:
            raise ValueError(f"Coordinate length {len(coord)} does not match histogram dimensionality {dims}")
        indices = []
        for dim, edge in enumerate(self.edges):
            idx = np.searchsorted(edge, coord[dim], side='right') - 1
            # Outside the range – ignore this point
            if idx < 0 or idx >= len(edge) - 1:
                return
            indices.append(idx)
        # Increment the appropriate bin
        self.hist[tuple(indices)] += weight
    elif coord.ndim == 2:
        # Broadcast fill over multiple points
        for point in coord:
            self.fill(point, weight)
    else:
        raise ValueError(f"Unsupported coordinate shape {coord.shape}")

