    import numpy as np

    coord = np.asarray(coord)

    # Determine number of dimensions
    if isinstance(self._edges, (list, tuple)):
        ndim = len(self._edges)
    else:  # assume numpy array with shape (ndim, n_bins+1)
        ndim = self._edges.shape[0]

    if coord.ndim == 0:
        coord = coord.reshape(1)

    if coord.size != ndim:
        raise ValueError(f"Coordinate dimension mismatch: expected {ndim}, got {coord.size}")

    # Find bin indices for each dimension
    indices = []
    for dim, edges in enumerate(self._edges):
        idx = np.searchsorted(edges, coord[dim], side='right') - 1
        if idx < 0 or idx >= len(edges) - 1:
            # Outside the histogram bounds; ignore
            return
        indices.append(idx)

    idx_tuple = tuple(indices)

    # Increment the count in the appropriate bin
    if np.isscalar(weight):
        self._counts[idx_tuple] += weight
    else:
        self._counts[idx_tuple] = np.add(self._counts[idx_tuple], weight)

def _validate_labels(labels):
    import re
    from django.core.exceptions import ValidationError
    key_pattern = re.compile(r'^[a-zA-Z0-9_]+$')
    errors = []
    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): 'expected string or bytes-like object'})
        else:
            if not key_pattern.match(key):
                errors.append({repr(key): f"Label key '{key}' does not match the regex {key_pattern.pattern}"})
        # Validate value type
        if not isinstance(value, (str, bytes)):
            errors.append({repr(key): 'expected string or bytes-like object'})
    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key‑value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # helper function to add an error
    def _add_error(key, msg):
        errors.append({key: msg})

    for k, v in labels.items():
        # --- key validation -------------------------------------------------
        if not isinstance(k, (str, bytes)):
            _add_error(str(k), "expected string or bytes-like object")
        else:
            if not re.fullmatch(K_KEY_REGEX, k):
                # Include the regex pattern only if defined in the error context
                _add_error(k, f"Label key '{k}' does not match the regex {K_KEY_REGEX}")

        # --- value validation ------------------------------------------------
        # If the value is a list, validate each element
        if isinstance(v, list):
            for elem in v:
                if not isinstance(elem, (str, bytes)):
                    _add_error(f"'{elem}'", "expected string or bytes-like object")
                else:
                    if not re.fullmatch(V_VALUE_REGEX, elem):
                        _add_error(f"'{elem}'", f"Label value '{elem}' does not match the regex {V_VALUE_REGEX}")
            # Also ensure the list itself is a list of valid elements
            if not isinstance(v, list):
                _add_error(str(v), "expected list")

        else:
            # Single value (not a list)
            if not isinstance(v, (str, bytes)):
                _add_error(str(v), "expected string or bytes-like object")
            else:
                if not re.fullmatch(V_VALUE_REGEX, v):
                    _add_error(v, f"Label value '{v}' does not match the regex {V_VALUE_REGEX}")

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re

    # Define the allowed pattern for keys and string values
    # (The actual pattern is not specified; a representative example is used)
    key_value_regex = re.compile(r'^[A-Za-z0-9_-]{1,64}$')

    messages = []

    for k, v in labels.items():
        # Validate key
        if not isinstance(k, (str, bytes)):
            messages.append({repr(k): 'expected string or bytes-like object'})
        else:
            try:
                if not key_value_regex.match(k):
                    messages.append({repr(k): f"Label key '{k}' does not match the regex [...]"})
            except Exception:
                # If the regex operation itself fails, record the underlying error
                messages.append({repr(k): 'expected string or bytes-like object'})

        # Validate value(s)
        # If the value is a list or tuple, validate each element
        if isinstance(v, (list, tuple)):
            for item in v:
                if not isinstance(item, (str, bytes)):
                    messages.append({repr(item): 'expected string or bytes-like object'})
                else:
                    try:
                        if not key_value_regex.match(item):
                            messages.append(
                                {repr(item): f"Label value '{item}' does not match the regex [...]"}
                            )
                    except Exception:
                        messages.append({repr(item): 'expected string or bytes-like object'})
        else:
            if not isinstance(v, (str, bytes)):
                messages.append({repr(v): 'expected string or bytes-like object'})
            else:
                try:
                    if not key_value_regex.match(v):
                        messages.append(
                            {repr(v): f"Label value '{v}' does not match the regex [...]"}
                        )
                except Exception:
                    messages.append({repr(v): 'expected string or bytes-like object'})

    if messages:
        raise ValidationError(messages)

def validate_key(key):
    """
    Validate the given key against the corresponding regular expression.
    """
    import re
    pattern = get_key_pattern(key)
    if not pattern:
        raise ValidationError(f"No regex pattern found for key {key}")
    if not re.fullmatch(pattern, key):
        raise ValidationError(f"Key '{key}' does not conform to the required pattern.")

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    # Helper for checking scalar types
    def is_scalar(v):
        return isinstance(v, (int, float, str, bool))

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Keep the list structure; replace scalar items with None, keep dict items processed
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # scalar or other non-dict/list values become None
            result[key] = None

    if first_level:
        # Preserve identifying fields that are scalar in the original manifest.
        # Common identifying fields: apiVersion, kind, name, namespace within metadata.
        if "apiVersion" in manifest_dict and is_scalar(manifest_dict["apiVersion"]):
            result["apiVersion"] = manifest_dict["apiVersion"]
        if "kind" in manifest_dict and is_scalar(manifest_dict["kind"]):
            result["kind"] = manifest_dict["kind"]
        if "metadata" in manifest_dict and isinstance(manifest_dict["metadata"], dict):
            # Ensure the metadata dict exists in the result and preserve its scalar fields.
            if "metadata" not in result or not isinstance(result["metadata"], dict):
                result["metadata"] = {}
            for m_key, m_value in manifest_dict["metadata"].items():
                if is_scalar(m_value):
                    result["metadata"][m_key] = m_value

    return result

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """
    Recursively update a list-structured ``last_applied_manifest`` using a
    matching ``observer_schema`` and ``response``.  Missing entries in
    ``last_applied_manifest`` are filled in from ``response``.
    """
    # Ensure we iterate over the shortest length of response and schema
    for idx, resp_value in enumerate(response):
        if idx >= len(observer_schema):
            break
        schema_item = observer_schema[idx]

        # If the schema is simply a scalar type (represented as a string)
        if isinstance(schema_item, str):
            if len(last_applied_manifest) <= idx:
                # Extend the list to fit the new item
                last_applied_manifest.append(resp_value)
            elif last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = resp_value
            continue

        # If the schema describes a nested structure
        if isinstance(schema_item, dict):
            field_name = schema_item.get('name')
            if field_name is None:
                # No explicit name; treat as a scalar placed at the index
                if len(last_applied_manifest) <= idx:
                    last_applied_manifest.append(resp_value)
                else:
                    last_applied_manifest[idx] = resp_value
                continue

            # Ensure a place exists for this field in the manifest
            if field_name not in last_applied_manifest:
                last_applied_manifest[field_name] = {}

            sub_manifest = last

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Use a helper that works with both dict and list structures
    def _update(target, schema, source):
        # If the schema is a mapping (dict), its keys are field names
        if isinstance(schema, dict):
            for key, sub_schema in schema.items():
                if key not in target:
                    # If the key is present in the source, set it
                    if key in source:
                        target[key] = source[key]
                else:
                    # If the field is nested, recurse into it
                    if isinstance(sub_schema, (dict, list)):
                        _update(target[key], sub_schema, source[key])
        # If it's a list, each item can be a field name or a tuple/list
        elif isinstance(schema, list):
            for item in schema:
                # Handle nested tuples/lists like ('field', sub_schema)
                if isinstance(item, (tuple, list)) and len(item) > 1:
                    field_name, sub_schema = item[0], item[1]
                else:
                    field_name, sub_schema = item, None

                if field_name not in target:
                    if field_name in source:
                        target[field_name] = source[field_name]
                else:
                    if sub_schema:
                        # Recurse with the nested target field
                        _update(target[field_name], sub_schema, source[field_name])

    _update(last_applied_manifest, observer_schema, response)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Ensure the target is a list
    if not isinstance(last_applied_manifest, list):
        last_applied_manifest = []

    # Iterate over response items
    for idx, resp_item in enumerate(response):
        # Make sure we have a dict to update
        if idx < len(last_applied_manifest):
            item = last_applied_manifest[idx]
        else:
            item = {}
            last_applied_manifest.append(item)

        # Now update fields defined in observer_schema
        for field in observer_schema:
            # Field can be a nested dict schema
            if isinstance(field, dict):
                # Kubernetes observer schema uses key '0' for field name and
                # 'value' for child schema
                field_name = field.get('0')
                child_schema = field.get('value')
                if not field_name:
                    continue
                # Ensure the child dict exists
                child_item = item.get(field_name)
                if child_item is None:
                    child_item = {}
                    item[field_name] = child_item
                # Recurse into the child structure; the child response is
                # expected to be a dict for dict schema or a list for list schema.
                child_resp = resp_item.get(field_name, {})
                if isinstance(child_schema, list):
                    update_last_applied_manifest_list_from_resp(
                        child_item, child_schema, child_resp
                    )
                else:
                    update_last_applied_manifest_dict_from_resp(
                        child_item, child_schema, child_resp
                    )
                continue

            # Simple field name (string)
            field_name = field
            if field_name not in item:
                item[field_name] = resp_item

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, sub_schema in observer_schema.items():
        if field not in response:
            raise KeyError(
                f"Observed field {field!r} not present in Kubernetes response"
            )
        # If the field has not yet been populated, set its value directly
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        # If the field is a nested mapping, recurse to populate nested fields
        if isinstance(sub_schema, dict) and isinstance(response[field], dict):
            # Ensure the nested structure exists in the manifest
            if not isinstance(last_applied_manifest[field], dict):
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], sub_schema, response[field]
            )
    return last_applied_manifest

