def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, sub_schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Missing key '{field}' in response")
        if field not in last_applied_manifest:
            if isinstance(sub_schema, dict):
                # Nested dictionary: create and recurse
                if not isinstance(response[field], dict):
                    raise KeyError(
                        f"Expected dict for nested field '{field}' in response"
                    )
                last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], sub_schema, response[field]
                )
            else:
                # Leaf field: set value directly
                last_applied_manifest[field] = response[field]
        else:
            # If the field already exists and is a dict, continue merging
            if isinstance(sub_schema, dict) and isinstance(response[field], dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], sub_schema, response[field]
                )
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Verify that the application has a spec and a manifest
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return

    # Ensure the observers container exists on the spec.
    # It could be a dict keyed by a resource identifier or a list of observer objects;
    # prefer a dict for idempotent default creation.
    observers = getattr(app.spec, "observers", None)
    if observers is None:
        observers = {}
        setattr(app.spec, "observers", observers)

    # Helper to create a unique key for a resource.  Use kind and name, optionally
    # namespace if present.
    def _resource_key(res):
        parts = [getattr(res, "kind", None), getattr(res, "name", None)]
        ns = getattr(res, "namespace", None)
        if ns:
            parts.append(ns)
        return "/".join(filter(None, parts))

    # Iterate over the manifest definitions.
    # The manifest may be a list or a mapping from identifiers to resource objects.
    manifest_iterable = app.spec.manifest
    if isinstance(manifest_iterable, dict):
        manifest_items = manifest_iterable.values()
    else:
        manifest_items = manifest_iterable

    for res in manifest_items:
        key = _resource_key(res)
        if not key:
            # Skip entries that don't provide enough information
            continue

        # Skip if a custom observer schema already exists for this resource
        if key in observers:
            continue

        # Build a minimal default observer schema for the resource.
        default_schema = {
            "kind": getattr(res, "kind", None),
            "apiVersion": getattr(res, "api_version", None),
            "metadata": {
                "name": getattr(res, "name", None),
                "namespace": getattr(res, "namespace", None),
                # Add a label pointing to the application for traceability
                "labels": {"krake.io/application": getattr(app, "name", None)},
            },
        }

        # Store the default schema in the observers mapping.
        observers[key] = default_schema

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the observer_schema attribute exists
    if not hasattr(app.spec, "observer_schema"):
        app.spec.observer_schema = {}

    for resource in getattr(app.spec, "manifest", []):
        kind = resource.get("kind")
        if not kind:
            continue

        # Skip resources that already have a custom observer schema
        if kind in app.spec.observer_schema:
            continue

        # Default observer schema: monitor name and namespace in metadata
        app.spec.observer_schema[kind] = {
            "metadata": {
                "name": str,
                "namespace": str,
            }
        }

    return app.spec.observer_schema

