    missing = [key for key in required_keys if key not in inventory]
    if missing:
        raise ArgumentError('inventory', f'Missing required keys: {missing}')
    # Validate components list
    components = inventory['components']
    if not isinstance(components, list):
        raise ArgumentError('components', 'Components must be a list')
    for idx, comp in enumerate(components):
        if not isinstance(comp, dict):
            raise ArgumentError('component', f'Component at index {idx} must be a dict')
        # Each component must have 'name' and 'type'
        if 'name' not in comp or 'type' not in comp:
            raise ArgumentError('component', f'Component at index {idx} missing required fields: {comp}')
