    """
    if not isinstance(inventory, dict):
        raise ArgumentError(
            "inventory",
            "Inventory must be a dictionary, got %s" % type(inventory).__name__,
        )

    # Determine the spec version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Map the type value to a specification version if known
            if hasattr(self, "type_to_spec_version") and type_val in self.type_to_spec_version:
                spec_version = self.type_to_spec_version[type_val]
        # If no valid type or mapping is not found, default spec_version remains

    # Retrieve the spec for the determined version
    spec = getattr(self, "spec", {}).get(spec_version, {})

    # Validate each field defined in the spec
    for field_name, field_spec in spec.items():
        # Skip optional fields that are absent
        if field_name not in inventory:
            if field_spec.get("required", False):
                raise ArgumentError(
                    field_name,
                    "Missing required field '%s' in inventory" % field_name,
                )
            continue

        value = inventory[field_name]

        # If a validator is provided in the spec, use it
        validator = field_spec.get("validator")
        if validator is not None:
            validator(value, field_name)

        # If the field type is a Schema, validate recursively
        if isinstance(field_spec.get("type"), Schema):
            if not isinstance(value, dict):
                raise ArgumentError(
                    field_name,
                    "Expected a dictionary for nested schema '%s', got %s"
                    % (field_name, type(value).__name__),
                )
            field_spec["type"].validate(value)

        # If the field type is an Array, validate each item
        if isinstance(field_spec.get("type"), Array):
            if not isinstance(value, list):
                raise ArgumentError(
                    field_name,
                    "Expected a list for field '%s', got %s" % (field_name, type(value).__name__),
                )
            item_validator = field_spec["type"].contained_type
            for idx, item in enumerate(value):
                if isinstance(item_validator, Schema):
                    item_validator.validate(item)
                else:
                    if not isinstance(item, item_validator):
                        raise ArgumentError(
                            f"{field_name}[{idx}]",
                            "Expected items of type %s, got %s"
                            % (item_validator.__name__, type(item).__name__),
                        )

    return inventory...

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict of filenames to digests")
    # Find any files whose digest is not in the used set
    missing_files = [fname for fname, digest in manifest_files.items()
                     if digest not in digests_used]
    if missing_files:
        raise ValueError("Missing digests for files: " + ", ".join(missing_files))
    # Find any digests that are used but not listed in the manifest
    unused_digests = [d for d in digests_used if d not in manifest_files.values()]
    if unused_digests:
        if hasattr(self, "logger"):
            self.logger.warn("Used digests not present in manifest: " +
                             ", ".join(unused_digests))
        else:
            print("Warning: Used digests not present in manifest:",
                  ", ".join(unused_digests))

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Build set of digests that appear in the manifest
    present_digests = set()
    for entry in manifest_files:
        # entry can be a dict or a tuple/list where the digest is the second element
        if isinstance(entry, dict):
            digest = entry.get("digest")
        else:
            # Assume the digest is at index 1 for tuples/lists
            if len(entry) > 1:
                digest = entry[1]
            else:
                digest = None
        if digest:
            present_digests.add(digest)

    digests_used_set = set(digests_used)

    # Check that every digest in the manifest is actually used
    missing_in_use = present_digests - digests_used_set
    if missing_in_use:
        raise ValueError(
            f"Digest(s) from manifest not used: {', '.join(sorted(missing_in_use))}"
        )

    # Optionally, also check that every used digest is present in the manifest
    unused = digests_used_set - present_digests
    if unused:
        raise ValueError(
            f"Used digest(s) not present in manifest: {', '.join(sorted(unused))}"
        )
    # No return value needed; success implies no exception was raised.

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # If either collection is empty, nothing to validate
    if not manifest_files or not digests_used:
        return

    # Collect the set of digests declared in the manifest
    try:
        # Assume a mapping of filename -> digest
        manifest_digests = set(manifest_files.values())
    except AttributeError:
        # Assume an iterable of (filename, digest) tuples
        manifest_digests = set(d for _, d in manifest_files)

    # Convert the provided digests to a set for set operations
    used_digests = set(digests_used)

    # Digests that are in the manifest but were never used
    missing_digests = manifest_digests - used_digests
    if missing_digests:
        raise ValueError(
            f"Digests in manifest that were never used: {sorted(missing_digests)}"
        )

    # Digests that were used but are not present in the manifest
    unused_digests = used_digests - manifest_digests
    if unused_digests:
        raise ValueError(
            f"Used digests that are not listed in the manifest: {sorted(unused_digests)}"
        )

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Build a set of digests that appear in the manifest
    if isinstance(manifest_files, dict):
        manifest_digests = set(manifest_files.keys())
    else:
        manifest_digests = set()
        for entry in manifest_files:
            if isinstance(entry, dict):
                digest = entry.get('digest')
            else:
                digest = getattr(entry, 'digest', None)
            if digest:
                manifest_digests.add(digest)

    # Determine which digests are missing from the used set
    missing_in_used = manifest_digests - set(digests_used)
    if missing_in_used:
        raise ValueError(f"Digests missing from usage: {sorted(missing_in_used)}")

    # Optionally, flag digests that are used but not present in the manifest
    unused_in_manifest = set(digests_used) - manifest_digests
    if unused_in_manifest:
        raise ValueError(f"Digests used but not present in manifest: {sorted(unused_in_manifest)}")

    return True

