            "constraints",
        ]

        for attr in attributes_to_check:
            if not hasattr(prior, attr) or not hasattr(self, attr):
                raise AttributeError(
                    f"Both inventories must define attribute '{attr}'"
                )
            prior_value = getattr(prior, attr)
            current_value = getattr(self, attr)
            # For containers compare element-wise; for matrices compare shape and dtype
            if isinstance(prior_value, (list, tuple, set)):
                if set(prior_value) != set(current_value):
                    raise ValueError(
