                        f"vs current has {sorted(current_value)}"
                    )
            elif hasattr(prior_value, "shape") and hasattr(current_value, "shape"):
                # matrix-like objects
                if prior_value.shape != current_value.shape:
                    raise ValueError(
                        f"Attribute '{attr}' shape mismatch: prior {prior_value.shape} "
                        f"vs current {current_value.shape}"
                    )
                # If they have a dtype attribute, also verify
                if hasattr(prior_value, "dtype") and hasattr(current_value, "dtype"):
                    if prior_value.dtype != current_value.dtype:
                        raise ValueError(
                            f"Attribute '{attr}' dtype mismatch: prior {prior_value.dtype} "
                            f"vs current {current_value.dtype}"
                        )
            else:
                # Generic equality check
                if prior_value != current_value:
                    raise ValueError(
                        f"Attribute '{attr}' differs between prior and current inventory"
                    )

        # Ensure no additional attributes in prior that are not present in current
        prior_attrs = set(dir(prior))
        # Filter out special and callable attributes
        prior_attrs = {a for a in prior_attrs if not a.startswith("_") and not callable(getattr(prior, a))}
        self_attrs = set(dir(self))
        self_attrs = {a for a in self_attrs if not a.startswith("_") and not callable(getattr(self, a))}
        # Any attribute in prior not expected or not present in current should raise error
        diff_attrs = prior_attrs - self_attrs
        if diff_attrs:
            raise ValueError(
                f"Prior contains unexpected attributes not present in current inventory: {sorted(diff_attrs)}"
            )

        # All checks passed
        return True

