    # Fallback: inventory may be a list of entries where each entry is a dict
    # containing the keys 'version', 'logical_path', and 'file'.
    result = {}
    for entry in inventory:
        if entry.get('version') == version:
            logical = entry.get('logical_path')
            file = entry.get('file')
