    def _compare_versions(v1, v2):
        """
        Compare two version strings.
        Return 1 if v1 > v2, 0 if equal, -1 if v1 < v2.
        """
        try:
            parts1 = [int(x) for x in v1.split('.')]
            parts2 = [int(x) for x in v2.split('.')]
        except Exception:
            # Fallback to simple string comparison
            if v1 == v2:
                return 0
            return 1 if v1 > v2 else -1

        # Pad the shorter list
        length = max(len(parts1), len(parts2))
        parts1.extend([0] * (length - len(parts1)))
        parts2.extend([0] * (length - len(parts2)))

        if parts1 > parts2:
            return 1
        if parts1 < parts2:
            return -1
        return 0

    def _is_version_greater_equal(candidate, target):
        """
        True if candidate version is greater than or equal to target version.
        """
        if target in (None, 'latest'):
