    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    for logical_path, entries in inventory.items():
        files = set()
        # Helper to add a content file if it meets version criteria
        def add_file(entry):
            # entry may be a dict with 'content_file' and 'version' keys
            if isinstance(entry, dict):
                entry_version = entry.get('version')
                # Include if version is unspecified or <= target version
                if entry_version is None or entry_version <= version:
                    content = entry.get('content_file')
                    if content:
                        files.add(content)
            else:
                # Assume entry is the content file path itself
                files.add(entry)

        if isinstance(entries, dict):
            # Dict mapping maybe version -> file or more nested dicts
            for key, val in entries.items():
                if isinstance(val, dict):
                    # Nested dicts may hold 'content_file' and 'version'
                    add_file(val)
                else:
                    # Direct mapping of version to content file string
                    files.add(val)
        elif isinstance(entries, list):
            for entry in entries:
                add_file(entry)
        else:
            # Single entry (string or dict)
            add_file(entries)

        if files:
            path_map[logical_path] = files
    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_map = {}

    for logical_path, versions in inventory.items():
        files_set = set()
        # Assume `versions` is a mapping of version -> iterable of file paths
        for v, files in versions.items():
            # Include files for the requested version and any later versions.
            if str(v) >= str(version):
                if isinstance(files, (list, set, tuple)):
                    files_set.update(files)
                else:
                    files_set.add(files)
        logical_map[logical_path] = files_set

    return logical_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

