def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    # Expected required keys
    required_keys = {"files", "checksum", "algorithm"}
    missing = required_keys - set(fixity.keys())
    if missing:
        raise ValueError(f"Fixity block missing required keys: {', '.join(sorted(missing))}")
    # Validate files
    files = fixity["files"]
    if not isinstance(files, (list, set)):
        raise ValueError("The 'files' entry must be a list or set")
    for file_path in files:
        if file_path not in manifest_files:
            raise ValueError(f"Fixity references unknown file '{file_path}'")
    # Validate algorithm
    algorithm = fixity["algorithm"]
    if algorithm not in ("sha256", "sha1", "md5"):
        raise ValueError(f"Unsupported checksum algorithm '{algorithm}'")
    # Validate checksum
    checksum = fixity["checksum"]
    if not isinstance(checksum, str) or not checksum:
        raise ValueError("Checksum must be a non-empty string")
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dict")

    # Check for algorithm key
    algorithm = fixity.get('algorithm') or fixity.get('checksum_algorithm')
    if not algorithm:
        raise ValueError("Fixity block missing required 'algorithm' key")

    # Validate files list
    files = fixity.get('files')
    if files is None:
        raise ValueError("Fixity block missing required 'files' key")
    if not isinstance(files, list):
        raise ValueError("'files' entry in fixity block must be a list")

    referenced = set()
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"Entry {idx} in 'files' list is not a dict")
        path = entry.get('path')
        checksum = entry.get('checksum')
        if path is None or checksum is None:
            raise ValueError(f"Entry {idx} missing 'path' or 'checksum'")
        if not isinstance(path, str):
            raise ValueError(f"'path' in entry {idx} must be a string")
        if not isinstance(checksum, str):
            raise ValueError(f"'checksum' in entry {idx} must be a string")

        if path not in manifest_files:
            raise ValueError(f"File '{path}' referenced in fixity block not found in manifest")
        referenced.add(path)

    # Ensure that every file in the manifest is referenced in the fixity block
    # (this is optional; adjust if only subset is allowed)
    for mfile in manifest_files:
        if mfile not in referenced:
            raise ValueError(f"File '{mfile}' present in manifest but not referenced in fixity block")

    # If we reach here, validation succeeded
    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

