    if 'hashes' not in fixity:
        raise ValueError("Fixity block must contain a 'hashes' key")
    hashes = fixity['hashes']
    if not isinstance(hashes, dict):
        raise ValueError("'hashes' must be a dictionary")
    for fname, entry in hashes.items():
        if not isinstance(fname, str):
            raise ValueError(f"File key {repr(fname)} in hash table must be a string")
        if fname not in manifest_files:
            raise ValueError(f"File '{fname}' referenced in fixity but not present in manifest")
        if not isinstance(entry, dict):
            raise ValueError(f"Hash entry for '{fname}' must be a dictionary")
        if 'value' not in entry:
            raise ValueError(f"Hash entry for '{fname}' missing 'value' key")
        if 'algorithm' not in entry:
            raise ValueError(f"Hash entry for '{fname}' missing 'algorithm' key")
        if entry['algorithm'] not in hashlib.algorithms_available:
            raise ValueError(f"Unknown hash algorithm '{entry['algorithm']}' for file '{fname}'")
    return True

