def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    package_data = {}

    # First pass: collect and parse each XML file
    for root, _, files in os.walk(folder):
        for fname in files:
            name, ext = os.path.splitext(fname)
            if ext.lower() == '.xml':
                xml_path = os.path.join(root, fname)
                try:
                    tree = ET.parse(xml_path)
                    xml_root = tree.getroot()

                    def elem_to_dict(elem):
                        d = {}
                        if elem.text and elem.text.strip():
                            d["#text"] = elem.text.strip()
                        for child in elem:
                            d.update({child.tag: elem_to_dict(child)})
                        return {elem.tag: d}

                    metadata = elem_to_dict(xml_root)[xml_root.tag]
                except ET.ParseError:
                    metadata = None

                package_data.setdefault(name, {})
                package_data[name]["metadata"] = metadata

    # Second pass: add any non-XML files to the same groups
    for root, _, files in os.walk(folder):
        for fname in files:
            name, ext = os.path.splitext(fname)
            if ext.lower() != '.xml':
                file_path = os.path.join(root, fname)
                package_data.setdefault(name, {})
                files_list = package_data[name].get("files", [])
                files_list.append(file_path)
                package_data[name]["files"] = files_list

    return package_data

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        filename

    Returns
    -------
    dict
    """
    package_info = {}
    try:
        with open(file_path, 'r', encoding='utf-8') as fp:
            # Read a small portion of the file to speed up detection
            snippet = fp.read(2048).lower()
        if '<rendition' in snippet:
            pkg_type = 'rendition'
        elif '<asset' in snippet:
            pkg_type = 'asset'
        else:
            pkg_type = 'unknown'
        package_info[prefix] = {'type': pkg_type, 'path': file_path}
    except (IOError, OSError) as exc:
        package_info[prefix] = {'type': 'error', 'path': file_path, 'error': str(exc)}
    return package_info

def add_rendition(self, lang, file_path):
    """{
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }"""
    base, ext = os.path.splitext(os.path.basename(file_path))
    original_file = base + ext
    rendition_file = f"{base}-{lang}{ext}"
    mapping = {"original": original_file, lang: rendition_file}
    if not hasattr(self, "_renditions"):
        self._renditions = {}
    self._renditions.update(mapping)
    return mapping

