def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    import pprint
    if debug:
        return f'{pprint.pformat(self, indent=indent)} (id={id(self)})'
    return pprint.pformat(self, indent=indent)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Use pprint's pformat for indentation; import lazily to avoid global imports.
    try:
        from pprint import pformat
        if debug:
            # Include all attributes (including private ones).
            attrs = {k: v for k, v in self.__dict__.items()}
        else:
            # Exclude private/internal attributes.
            attrs = {k: v for k, v in self.__dict__.items() if not k.startswith('_')}
        # `indent` controls indentation in spaces per level.
        return pformat(attrs, indent=indent)
    except Exception:
        # Fallback: use repr if anything goes wrong.
        return repr(self)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    if indent < 0:
        indent = 0
    try:
        import pprint
        # If debugging, add a stack trace before returning
        if debug:
            import traceback, sys
            traceback.print_exc(file=sys.stdout)
        return pprint.pformat(self, depth=None, indent=indent)
    except Exception:
        # Fallback to a plain string representation
        return str(self)

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        prefix = ' ' * indent
        if debug:
            items = []
            for k, v in vars(self).items():
                items.append(f"{k}={repr(v)}")
            body = ", ".join(items)
            return f"{prefix}<{self.__class__.__name__}({body})>"
        else:
            return f"{prefix}{repr(self)}"

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

