def get_versions(default="unknown"):
    """Get version information or return default if unable to do so."""
    try:
        try:
            from importlib.metadata import distributions
        except Exception:
            try:
                from importlib_metadata import distributions
            except Exception:
                # If importlib.metadata or its backport is unavailable
                return default

        versions = {}
        for dist in distributions():
            name = dist.metadata.get("Name")
            if not name:
                continue
            # Use the distribution's version, fallback to default if None
            versions[name] = dist.version if dist.version else default

        return versions
    except Exception:
        # If any unexpected error occurs, return the default value
        return default

