def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == 'html':
        return ''.join(f'<p>{p}</p>' for p in pieces)
    elif style in ('markdown', 'md'):
        return '\n\n'.join(pieces)
    elif style == 'json':
        import json
        return json.dumps(pieces)
    else:
        return '\n'.join(pieces)

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Handle empty or falsy input
    if not pieces:
        return ''
    # If `pieces` is a mapping: look for typical semver keys
    if isinstance(pieces, dict):
        major = pieces.get('major', 0)
        minor = pieces.get('minor', 0)
        patch = pieces.get('patch', 0)
        pre_release = pieces.get('pre_release')
        build = pieces.get('build')
        base = f"{major}.{minor}.{patch}"
        if style == 'semver':
            return base
        if style == 'semver_pre':
            return f"{base}-{pre_release}" if pre_release else base
        if style == 'semver_build':
            return f"{base}+{build}" if build else base
        if style == 'short':
            return f"{major}.{minor}"
        if style == 'full':
            return base
        # Custom pattern with str.format
        try:
            return style.format(
                major=major, minor=minor, patch=patch,
                pre_release=pre_release or '', build=build or '')
        except Exception:
            pass
    # If `pieces` is an ordered sequence: join according to style
    if isinstance(pieces, (list, tuple)):
