    values = []
    for piece in pieces:
        if isinstance(piece, dict):
            for k, v in piece.items():
                values.append((k, v))
        else:
            # Try to extract attributes from objects
            for attr in dir(piece):
                if attr.startswith('_'):
                    continue
                try:
                    val = getattr(piece, attr)
                except Exception:
                    continue
                if val is not None:
                    values.append((attr, val))
    # Handle different rendering styles
    if style == 'short':
        return ' '.join(f'{k}:{v}' for k, v in values)
    elif style == 'dot':
        return '.'.join(str(v) for k, v in values)
    else:  # default full representation
        return ', '.join(f'{k}={v}' for k, v in values)

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, (dict, list, tuple)):
        raise TypeError("pieces must be a sequence or mapping")

    # Style: 'semantic' → semantic versioning string
    #        'pretty'   → human‑readable string
    #        anything else → fallback to string conversion
    if style == "semantic":
        seq = list(pieces)
        # Major, minor, patch
        version = ".".join(str(seq[i]) for i in range(min(3, len(seq))))
        suffix = ""

        # pre_release
        if len(seq) > 3 and seq[3] is not None:
            suffix += "-" + str(seq[3])

        # build metadata
        if len(seq) > 4 and seq[4] is not None:
            suffix += "+" + str(seq[4])
        return version + suffix

    if style == "pretty":
        if isinstance(pieces, dict):
            return ", ".join(f"{k}={v}" for k, v in pieces.items())
        return ", ".join(str(p) for p in pieces)

    return str(pieces)

