def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    for obj in self._get_all_objects():
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                self._validate_object(obj)
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Validation failed for {obj}: {e}")

        if check_digests:
            try:
                expected = self._get_expected_digest(obj)
                actual = self._get_actual_digest(obj)
                if expected != actual:
                    is_valid = False
                    if show_warnings:
                        print(f"Digest mismatch for {obj}: expected {expected}, got {actual}")
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Digest check error for {obj}: {e}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import json
    import hashlib

    if not hasattr(self, "root_path"):
        raise AttributeError("Instance must have a 'root_path' attribute pointing to the hierarchy root directory.")

    total_objects = 0
    valid_objects = 0

    def _object_valid(obj_data, obj_path):
        """Validate a single object's metadata."""
        # Basic sanity checks
        if validate_objects:
            # Ensure the top-level JSON is a dict and contains required keys
            required_keys = {"id", "type", "content"}
            missing = required_keys - obj_data.keys()
            if missing:
                if show_warnings:
                    print(f"WARNING: {obj_path} missing keys {missing}")
                return False

        if check_digests:
            # Compute hash of the JSON content (excluding the checksum field if present)
            checksum_in_file = obj_data.get("checksum")
            obj_copy = dict(obj_data)
            obj_copy.pop("checksum", None)
            m = hashlib.sha256()
            # Use json.dumps with sorted keys for deterministic hashing
            m.update(json.dumps(obj_copy, sort_keys=True).encode("utf-8"))
            computed_checksum = m.hexdigest()
            if checksum_in_file and checksum_in_file != computed_checksum:
                if show_warnings:
                    print(f"WARNING: Checksum mismatch in {obj_path}")
                return False

        return True

    # Walk through the root directory looking for JSON files
    for dirpath, _, filenames in os.walk(self.root_path):
        for filename in filenames:
            if not filename.lower().endswith(".json"):
                continue
            file_path = os.path.join(dirpath, filename)
            total_objects += 1
            try:
                with open(file_path, "r", encoding="utf-8") as fh:
                    data = json.load(fh)
            except Exception as exc:
                if show_warnings:
                    print(f"WARNING: Unable to load {file_path}: {exc}")
                continue

            if _object_valid(data, file_path):
                valid_objects += 1

    return total_objects, valid_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    # Retrieve the collection of objects that comprise the hierarchy.
    # The attribute name may vary; fall back to an empty dict if not present.
    objects = getattr(self, 'objects', getattr(self, 'hierarchy', {}))
    if not isinstance(objects, dict):
        # If objects is not a dict, nothing to validate.
        return 0, 0

    for obj_id, obj in objects.items():
        num_objects += 1
        valid = True

        if validate_objects:
            validate_method = getattr(obj, 'validate', None)
            if callable(validate_method):
                try:
                    validate_method()
                except Exception as e:  # pylint: disable=broad-except
                    valid = False
                    if show_warnings:
                        print(f"Warning: validation failed for object {obj_id}: {e}")

        if valid and check_digests:
            digest_method = getattr(obj, 'check_digest', None)
            if callable(digest_method):
                try:
                    if not digest_method():
                        valid = False
                        if show_warnings:
                            print(f"Warning: digest mismatch for object {obj_id}")
                except Exception as e:  # pylint: disable=broad-except
                    valid = False
                    if show_warnings:
                        print(f"Warning: digest check error for object {obj_id}: {e}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        (num_objects, good_objects) – number of objects checked
        good_objects – number of objects checked that were found to be valid
    """
    # Determine root object
    root = getattr(self, 'root', None) or getattr(self, '_root', None)
    if not root:
        return 0, 0

    num_objects = 0
    good_objects = 0

    def _walk(obj):
        nonlocal num_objects, good_objects
        num_objects += 1
        good = True

        if validate_objects:
            try:
                # Assume objects expose a validate() method that raises on failure
                obj.validate()
            except Exception as exc:
                good = False
                if show_warnings:
                    print(f"Validation error for {obj}: {exc}")

        if check_digests:
            try:
                # If the object has a verify_digest method, use it
                if hasattr(obj, 'verify_digest'):
                    if not obj.verify_digest():
                        good = False
                        if show_warnings:
                            print(f"Digest mismatch for {obj}")
            except Exception as exc:
                good = False
                if show_warnings:
                    print(f"Digest check error for {obj}: {exc}")

        if good:
            good_objects += 1

        # Recursively walk child objects, if any
        children = getattr(obj, 'children', [])
        if children is None:
            children = []
        for child in children:
            _walk(child)

    try:
        _walk(root)
    except Exception as exc:
        if show_warnings:
            print(f"Error walking hierarchy: {exc}")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return str(version)
    if not version.isdigit():
        return version
    width = len(version)
    try:
        new_num = int(version) + 1
    except Exception:
        return version
    return f"{new_num:0{width}d}"

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return version
    parts = version.split('.')
    # Only process numeric parts
    for i in range(len(parts)-1, -1, -1):
        try:
            num = int(parts[i])
            new_num = str(num + 1).zfill(len(parts[i]))
            parts[i] = new_num
            # Only bump the last numeric part
            break
        except ValueError:
            continue
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not hasattr(self, 'root_inventory'):
        raise AttributeError("root_inventory attribute missing")
    root_inv = self.root_inventory
    if not isinstance(root_inv, dict):
        raise TypeError("root_inventory must be a mapping")
    if not hasattr(self, 'inventory_differences'):
        self.inventory_differences = []
    seen_keys = set()
    for v_dir in version_dirs:
        inv = self.read_inventory(v_dir)
        if inv is None:
            raise ValueError(f"Missing inventory in version directory '{v_dir}'")
        if not isinstance(inv, dict):
            raise TypeError(f"Inventory in '{v_dir}' must be a mapping")
        # Ensure inventory covers all keys seen so far
        missing = seen_keys - set(inv.keys())
        if missing:
            raise ValueError(
                f"Inventory '{v_dir}' missing entries from earlier versions: "
                f"{', '.join(sorted(missing))}"
            )
        # Record digest discrepancies with the root inventory
        for key, digest in inv.items():
            root_digest = root_inv.get(key)
            if root_digest is not None and digest != root_digest:
                self.inventory_differences.append(
                    (v_dir, key, digest, root_digest)
                )
        seen_keys.update(inv.keys())
    return self.inventory_differences

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f'path does not exist: {path}'
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except Exception as e:
            return f'cannot list directory {path}: {e}'

        # Check for a Namaste file directly in this directory
        if any(entry.startswith('0=') for entry in entries):
            return 'object'

        # Look one level deeper for Namaste files; this indicates a storage root
        for entry in entries:
            subpath = os.path.join(path, entry)
            if os.path.isdir(subpath):
                try:
                    sub_entries = os.listdir(subpath)
                except Exception:
                    continue
                if any(e.startswith('0=') for e in sub_entries):
                    return 'root'

        return 'unknown or not an OCFL structure'

    return f'unknown path type: {path}'

def amend_bzparams(self, params, bug_ids):
