def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    # Helper to decide if a node is a MappingNode
    def is_mapping(node):
        # Mapping nodes have a tag that starts with the YAML map tag
        return hasattr(node, "tag") and node.tag.startswith("tag:yaml.org,2002:map")

    merged_entries = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_entries:
            existing_key_node, existing_value_node = merged_entries[key]
            if is_mapping(existing_value_node) and is_mapping(value_node):
                # Merge two MappingNodes recursively
                merged_value = type(existing_value_node)(
                    existing_value_node.tag,
                    deep_merge_nodes(existing_value_node.value + value_node.value),
                )
                merged_entries[key] = (existing_key_node, merged_value)
            else:
                # Non‑mapping values: last value wins
                merged_entries[key] = (existing_key_node, value_node)
        else:
            # First occurrence of this key
            merged_entries[key] = (key_node, value_node)

    return list(merged_entries.values())

