    ]

    return results, remaining

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, Node) pairs, merging mapping values with
    the same key. For non-mapping values, the last value wins.
    """
    def _merge_mapping_nodes(a, b):
        """Merge two ruamel.yaml MappingNode instances."""
        merged = {}
        # Preserve key node from the first mapping (a) when duplicates appear.
        for key_node, val_node in a.value:
            key_id = (key_node.tag, key_node.value)
            merged[key_id] = (key_node, val_node)
        for key_node, val_node in b.value:
            key_id = (key_node.tag, key_node.value)
            if key_id in merged:
                existing_key_node, existing_val_node = merged[key_id]
                if isinstance(val_node, MappingNode) and isinstance(existing_val_node, MappingNode):
                    merged_val = _merge_mapping_nodes(existing_val_node, val_node)
                    merged[key_id] = (existing_key_node, merged_val)
                else:
                    merged[key_id] = (existing_key_node, val_node)
            else:
                merged[key_id] = (key_node, val_node)
        return MappingNode(b.tag, [pair for _, pair in merged.values()])

    result = {}
    for key_node, val_node in nodes:
        key_id = (key_node.tag, key_node.value)
        if key_id in result:
            existing_key_node, existing_val_node = result[key_id]
            if isinstance(val_node, MappingNode) and isinstance(existing_val_node, MappingNode):
                merged_val = _merge_mapping_nodes(existing_val_node, val_node)
                result[key_id] = (existing_key_node, merged_val)
            else:
                result[key_id] = (existing_key_node, val_node)
        else:
            result[key_id] = (key_node, val_node)
    return [pair for _, pair in result.values()]}

