        remaining_args = [arg for arg in unparsed_arguments if arg in unclaimed_set]
    else:
        remaining_args = list(unparsed_arguments)

    return parsed, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    # Normalize input
    s = size.strip().upper()
    if not s:
        raise ValueError("Input string is empty")

    # Separate numeric part from unit part
    num_part = ""
    unit_part = ""
    for ch in s:
        if ch.isdigit() or ch == ".":
            num_part += ch
        else:
            unit_part += ch

    if not num_part:
        raise ValueError(f"Invalid size string: {size}")

    # Determine multiplier based on unit
    unit = unit_part.strip()
    if unit in ("", "B"):
        multiplier = 1
    elif unit in ("K", "KB"):
        multiplier = 1000
    elif unit in ("M", "MB"):
        multiplier = 1000**2
    elif unit in ("G", "GB"):
        multiplier = 1000**3
    elif unit in ("T", "TB"):
        multiplier = 1000**4
    elif unit in ("P", "PB"):
        multiplier = 1000**5
    elif unit in ("E", "EB"):
        multiplier = 1000**6
    else:
        raise ValueError(f"Unknown unit in size string: {size}")

    # Compute bytes and round to nearest integer
    bytes_value = float(num_part) * multiplier
    return int(round(bytes_value))

