    for key, value in url_args.items():
        if value is None:
            continue
        placeholder_braces = f'{{{key}}}'
        placeholder_colon = f':{key}'
        url = url.replace(placeholder_braces, str(value))
        url = url.replace(placeholder_colon, str(value))

    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # If no URL or no arguments, nothing to replace
    if not url:
        return url
    if not url_args:
        return url

    # Pattern matches {var} placeholders
    pattern = re.compile(r'\{([a-zA-Z0-9_]+)\}')

    def _replace_match(match):
        key = match.group(1)
        # Use provided value if present, otherwise keep the placeholder
        if key in url_args:
            return str(url_args[key])
        return match.group(0)

    return pattern.sub(_replace_match, url)

