def int_to_string(number: int, alphabet: list, padding: int | None = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            n, r = divmod(n, base)
            digits.append(alphabet[r])
        digits.reverse()
    if padding is not None and padding > 0:
        pad_len = max(0, padding - len(digits))
        if pad_len:
            digits = [alphabet[0]] * pad_len + digits
    return "".join(digits)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
