def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    # Treat "always" in a case‑insensitive manner
    if isinstance(frequency, str) and frequency.strip().lower() == "always":
        return None

    # Ensure we are working with a string for parsing
    freq_str = str(frequency).strip()
    import re
    # Regex to capture one or more digits followed by optional whitespace and letters
    m = re.match(r'^(\d+)\s*([a-zA-Z]+)$', freq_str)
    if not m:
        raise ValueError(f"Invalid frequency format: {frequency!r}")

    value = int(m.group(1))
    unit = m.group(2).lower()

    # Map the unit to a timedelta keyword argument
    if unit in ("second", "seconds"):
        return datetime.timedelta(seconds=value)
    if unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=value)
    if unit in ("hour", "hours"):
        return datetime.timedelta(hours=value)
    if unit in ("day", "days"):
        return datetime.timedelta(days=value)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=value)
    if unit in ("month", "months"):
        # Approximating a month as 30 days
        return datetime.timedelta(days=30 * value)
    if unit in ("year", "years"):
        # Approximating a year as 365 days
        return datetime.timedelta(days=365 * value)

    raise ValueError(f"Unknown time unit: {unit!r}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or str(frequency).strip().lower() == 'always':
        return None

    freq = str(frequency).strip()
    if not freq:
        raise ValueError('Empty frequency string')

    # Regular expression to capture number and unit
    import re
    m = re.match(r'^([0-9]+(?:\.[0-9]+)?)\s*([a-zA-Z]+)$', freq)
    if not m:
        raise ValueError(f'Could not parse frequency: {frequency!r}')
    num_str, unit = m.group(1), m.group(2).lower()

    try:
        count = int(float(num_str))
    except ValueError:
        raise ValueError(f'Invalid numeric value in frequency: {num_str!r}')

    # Normalize unit to singular
    unit = unit.rstrip('s')
    # Mapping from unit to timedelta keyword argument
    if unit in ('s', 'second', 'sec', 'secs'):
        return datetime.timedelta(seconds=count)
    if unit in ('m', 'minute', 'min', 'mins'):
        return datetime.timedelta(minutes=count)
    if unit in ('h', 'hour', 'hr', 'hrs'):
        return datetime.timedelta(hours=count)
    if unit in ('d', 'day'):
        return datetime.timedelta(days=count)
    if unit in ('w', 'week'):
        return datetime.timedelta(weeks=count)
    if unit in ('mo', 'month'):
        return datetime.timedelta(days=count * 30)  # approximate
    if unit in ('y', 'year'):
        return datetime.timedelta(days=count * 365)  # approximate

    raise ValueError(f'Unrecognized time unit in frequency: {unit!r}')

