def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Prepare the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        # If args is a list/tuple, extend; otherwise treat as single argument
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)

    # Verbose output
    if verbose:
        print(f"Running command: {' '.join(cmd)}")

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
            text=True,
            check=True if hide_stderr else False
        )
    except subprocess.CalledProcessError as e:
        # If hide_stderr is False, capture stderr; else it goes to DevNull
        error_output = e.stderr if e.stderr is not None else ''
        raise RuntimeError(f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}: {error_output}") from e

    # Return completed process-like object or dict with stdout, stderr, returncode
    return {
        'stdout': result.stdout,
        'stderr': result.stderr,
        'returncode': result.returncode
    }

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize the commands input; it can be a single command or an iterable of commands.
    if isinstance(commands, (list, tuple)):
        cmd_list = commands
    else:
        cmd_list = [commands]

    # Normalise args to a list
    if args is None:
        args_list = []
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        args_list = [args]

    results = {}
    for cmd in cmd_list:
        # Build the full command: if cmd is already a list, use it; otherwise treat as a single-token list.
        if isinstance(cmd, (list, tuple)):
            full_cmd = list(cmd)
        else:
            full_cmd = [cmd]

        # Append the arguments
        full_cmd.extend(args_list)

        if verbose:
            print(f"Running command: {full_cmd}")

        # Set up the stderr handling
        stderr = subprocess.DEVNULL if hide_stderr else None

        try:
            output = subprocess.check_output(
                full_cmd,
                cwd=cwd,
                stderr=stderr,
                env=env,
                text=True
            )
        except subprocess.CalledProcessError as exc:
            # Propagate the exception with the command that failed
            raise RuntimeError(f"Command {full_cmd!r} failed with exit code {exc.returncode}") from exc

        results[tuple(full_cmd)] = output

    return results

