            if fn.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif fn.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            elif fn.lower().endswith('.json'):
                cfg = json.loads(raw)
            else:
                # try YAML as fallback
                try:
                    cfg = yaml.safe_load(raw)
                except Exception:
                    record = logging.LogRecord(
                        'config_loader', logging.ERROR, fn, 0,
                        f'Unknown configuration file format: {fn}', None, None)
                    errors.append(record)
                    continue
            if not isinstance(cfg, dict):
                record = logging.LogRecord(
                    'config_loader', logging.ERROR, fn, 0,
                    f'Configuration is not a dict in file: {fn}', None, None)
                errors.append(record)
                continue
            if overrides:
                cfg.update(overrides)
            if resolve_env:
                cfg = _expand_env(cfg)
            configs[fn] = cfg
        except Exception as exc:
            exc_info = sys.exc_info()
            record = logging.LogRecord(
                'config_loader', logging.ERROR, fn, 0,
                f'Error parsing configuration file: {fn}', None, exc_info)
            errors.append(record)
    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return the results as a tuple of:
    - dict of configuration filename to corresponding parsed configuration,
    - sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import logging
    try:
        import toml
    except ImportError:
        toml = None
    try:
        import yaml
    except ImportError:
        yaml = None

    def _resolve_env_vars(value):
        if isinstance(value, dict):
            return {k: _resolve_env_vars(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env_vars(v) for v in value]
        if isinstance(value, str):
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, value)
        return value

    results = {}
    error_records = []
    logger = logging.getLogger(__name__)

    for cfg_file in config_filenames:
        try:
            if not os.path.isfile(cfg_file):
                raise FileNotFoundError(f"Configuration file not found: {cfg_file}")

            with open(cfg_file, 'r', encoding='utf-8') as f_obj:
                raw = f_obj.read()

            # Determine parser based on extension
            ext = os.path.splitext(cfg_file)[1].lower()
            if ext == '.toml' and toml is not None:
                parsed = toml.loads(raw)
            elif ext in {'.yaml', '.yml'} and yaml is not None:
                parsed = yaml.safe_load(raw)
            else:
                # Attempt safe yaml parse as fallback
                if yaml is not None:
                    parsed = yaml.safe_load(raw)
                else:
                    raise RuntimeError("No suitable parser available for the file extension")

            if not isinstance(parsed, dict):
                raise ValueError("Parsed configuration is not a dictionary")

            if overrides:
                if not isinstance(overrides, dict):
                    raise ValueError("Overrides must be a dictionary")
                parsed.update(overrides)

            if resolve_env:
                parsed = _resolve_env_vars(parsed)

            results[cfg_file] = parsed

        except Exception as exc:
            message = f"Error loading configuration '{cfg_file}': {exc}"
            record = logger.makeRecord(logger.name, logging.ERROR, cfg_file, 0, message, None, exc)
            error_records.append(record)

    return results, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os, json, yaml, toml, re
    configs = {}
    error_records = []

    def _parse_file(fname):
        try:
            with open(fname, 'r') as fd:
                raw = fd.read()
            ext = os.path.splitext(fname)[1].lower()
            if ext in ('.yaml', '.yml'):
                return yaml.safe_load(raw)
            elif ext == '.toml':
                return toml.loads(raw)
            elif ext == '.json':
                return json.loads(raw)
            else:
                # Unknown format: treat as text file
                return raw
        except Exception as exc:
            record = logging.LogRecord(name=__name__, level=logging.ERROR,
                                       pathname=fname, lineno=0,
                                       msg=str(exc), args=(), exc_info=None)
            error_records.append(record)
            return None

    def _apply_overrides(conf):
        if overrides and isinstance(conf, dict):
            for key, val in overrides.items():
                conf[key] = val

    def _replace_env(value):
        if isinstance(value, str):
            # replace ${VAR} with environment variable or empty string if missing
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            return re.sub(r'\$\{([^}]+)\}', repl, value)
        elif isinstance(value, dict):
            return {k: _replace_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_replace_env(v) for v in value]
        else:
            return value

    for fname in config_filenames:
        cfg = _parse_file(fname)
        if cfg is not None:
            _apply_overrides(cfg)
            if resolve_env:
                cfg = _replace_env(cfg)
            configs[fname] = cfg

    return configs, error_records

