@classmethod
def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    handlers = {}
    registry = getattr(cls, "_bolt_protocol_handlers", {})

    if protocol_version is None:
        # Return all supported handlers
        for ver, handler in registry.items():
            if isinstance(ver, tuple):
                handlers[ver] = handler
    else:
        # Return the handler for the requested version if it exists
        handler = registry.get(protocol_version)
        if handler is not None:
            handlers[protocol_version] = handler

    return handlers

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    handlers = {}
    for base in cls.__mro__:
        for name, value in base.__dict__.items():
            if isinstance(value, type) and hasattr(value, "PROTOCOL_VERSION"):
                ver = getattr(value, "PROTOCOL_VERSION")
                # Only add if it's a tuple of integers to avoid accidental keys
                if isinstance(ver, tuple) and all(isinstance(v, int) for v in ver):
                    handlers[ver] = value

    if protocol_version is not None:
        return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}
    return handlers

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq itself is a recognised sequence type, use it directly
    if isinstance(seq, (list, tuple, set, str, bytes)):
        return seq, type(seq)
    # Otherwise try to convert to a list; if that fails, wrap as single element
    try:
        seq = list(seq)
    except Exception:
        seq = [seq]
    return seq, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""
    # If *seq* is already a list or tuple, return it unchanged.
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    # For other iterables we convert to a list and remember the original type.
    try:
        seq_list = list(seq)
    except Exception as exc:
        raise TypeError(f"Object {seq!r} is not an iterable.") from exc

    return seq_list, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a standard sequence type (list or tuple), return it unchanged
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    # If seq is iterable (but not a string or bytes), convert it to a list
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        if bufsize is not None:
            import itertools
            sequence = list(itertools.islice(seq, bufsize))
        else:
            sequence = list(seq)
        return sequence, type(seq)
    # Otherwise (non-iterable or a string/bytes), treat seq as a single element
    return [seq], type(seq)

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Helper: compute current scale from last coordinate
    def _current_scale():
        if not hasattr(self, "_data"):
            raise LenaValueError("Graph data not found.")
        data = self._data
        if data.ndim < 2 or data.shape[1] == 0:
            raise LenaValueError("No coordinates available to compute scale.")
        last_col = data[:, -1]
        return float(np.max(np.abs(last_col)))

    if other is None:
        return _current_scale()

    # Only allow numeric values for rescaling
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a numeric value representing the desired scale")

    curr = _current_scale()
    if curr == 0:
        raise LenaValueError("Current scale is zero; cannot rescale.")
    factor = float(other) / curr

    # Rescale the last coordinate
    if hasattr(self, "_data"):
        self._data[:, -1] *= factor
    else:
        raise LenaValueError("Graph data not found; cannot rescale.")

    # Rescale any associated errors if present
    if hasattr(self, "_errors"):
        err = self._errors
        if err.ndim >= 2 and err.shape[1] == self._data.shape[1]:
            err[:, -1] *= factor

    return self

