def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    url_re = re.compile(r'(https?://[^\s]+|[^\s]+\.[^\s]+)')
    def maybe_add_link(match):
        url = match.group(0)
        if url.startswith('http'):
            href = url
        else:
            path = url
            if not os.path.isabs(path):
                path = os.path.relpath(path)
            if os.path.exists(path):
                href = f'/browse/{path}'
            else:
                return url
        return f'<a target="_blank" href="{href}">{url}</a>'
    return url_re.sub(maybe_add_link, text)

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if scheme not in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = Request(url, method='HEAD', headers={'Host': netloc})
    try:
        resp = urlopen(req)
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type')
    finally:
        resp.close()

