    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    default_path = "/nodeinfo/2.0"
    path = document_path if document_path else default_path
    if not path.startswith("/"):
        path = "/" + path
    href = url.rstrip("/") + path
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """ Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from lxml import etree
        import xmlsec
    except Exception:
        # Required libraries are not available
        return False

    # Parse the signed XML document
    try:
        root = etree.fromstring(doc)
    except etree.XMLSyntaxError:
        return False

    # Locate the Signature element in the XML tree
    sig_node = xmlsec.tree.find_node(root, xmlsec.Node.SIGNATURE)
    if sig_node is None:
        return False

    # Load the provided public key (assumed PEM format)
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception:
        return False

    # Create a SignatureContext, attach the key, and perform verification
    ctx = xmlsec.SignatureContext()
    ctx.key = key
    try:
        ctx.verify(sig_node)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception:
        return False

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Parse the XML document and signature if they are supplied as strings
    try:
        from lxml import etree
    except ImportError:
        return False

    def _to_element(value):
        if isinstance(value, str):
            return etree.fromstring(value)
        return value

    xml_doc = _to_element(doc)
    sig_elem = _to_element(signature) if signature else None

    # If no separate signature provided, try to find it in the document
    if sig_elem is None:
        ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}
        sig_elem = xml_doc.find('.//ds:Signature', namespaces=ns)
        if sig_elem is None:
            return False

    # Attempt to verify using xmlsec
    try:
        import xmlsec
    except ImportError:
        return False

    # Load the public key
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception:
        return False

    # Set up a signature context and try verification
    ctx = xmlsec.SignatureContext()
    ctx.key = key
    try:
        return ctx.verify(sig_elem)
    except xmlsec.VerificationError:
        return False
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    links = []
    subject = None
    hcard_url = None
    try:
        data = json.loads(document)
        subject = data.get("subject")
        for link in data.get("links", []):
            rel = link.get("rel")
            href = link.get("href")
            links.append({"rel": rel, "href": href})
            if rel == "hcard":
                hcard_url = href
    except json.JSONDecodeError:
        try:
            root = ET.fromstring(document)
            subject_el = root.find("{*}Subject")
            if subject_el is not None:
                subject = subject_el.text
            for link in root.findall("{*}Link"):
                rel = link.attrib.get("rel")
                href = link.attrib.get("href")
                links.append({"rel": rel, "href": href})
                if rel == "hcard":
                    hcard_url = href
        except ET.ParseError:
            return None
    return {"subject": subject, "hcard_url": hcard_url, "links": links}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try JSON first
    try:
        data = json.loads(document)
        # Flatten properties if present
        props = data.get("properties", {})
        if isinstance(props, dict):
            data.update(props)
        return data
    except Exception:
        pass

    # Fallback to XML/XRD parsing
    try:
        tree = ElementTree.fromstring(document)
        result: Dict[str, Any] = {}

        # Namespace handling if needed
        def _ns(tag: str, ns: str = "http://docs.oasis-open.org/ns/xri/xrd-1.0"):
            return f"{{{ns}}}{tag}"

        subject = tree.find(_ns("subject"))
        if subject is not None and subject.text:
            result["subject"] = subject.text.strip()

        aliases = [alias.text for alias in tree.findall(_ns("alias")) if alias.text]
        if aliases:
            result["aliases"] = aliases

        # Extract link relations
        links = []
        for link in tree.findall(_ns("link")):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                links.append({"rel": rel, "href": href})
        if links:
            result["links"] = links

        # Extract property tags (e.g., hcard_url)
        for prop in tree.findall(_ns("property")):
            name = prop.get("name")
            value = prop.text
            if name and value:
                result[name] = value.strip()

        return result if result else None
    except Exception:
        return None

