def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        user, host = handle.split("@")
    except ValueError:
        return None
    try:
        url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
    except NameError:
        url = "https://{}/.well-known/webfinger?resource=acct:{}".format(host, handle)
    try:
        with closing(urllib2.urlopen(url)) as page:
            content = page.read()
            if isinstance(content, bytes):
                return content.decode('utf-8', errors='replace')
            return content
    except Exception:
        return None

