def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s", url, data, timeout, method)
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data,
        "timeout": timeout,
        "headers": headers
    })
    method = method.lower()
    request_func = None
    if method == "post":
        request_func = requests.post
    elif method == "get":
        request_func = requests.get
    else:
        raise ValueError(f"Unsupported request method: {method}")
    try:
        response = request_func(url, *args, **kwargs)
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Parameters
    ----------
    settings_dirs : Iterable[str]
        List of directory paths to search for files.
    spec_option : str
        Filename pattern to match (e.g., '*.ini' or '.config').

    Returns
    -------
    List[str]
        Sorted list of fully qualified file paths that match the given pattern.
    """
    matched_files = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if fnmatch.fnmatch(fname, spec_option):
                    matched_files.append(os.path.join(directory, fname))
        except OSError:
            continue
    return sorted(matched_files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    import os
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)
    # Determine extension filter from spec_option if provided
    ext = None
    if isinstance(spec_option, dict):
        ext = spec_option.get("extension")
    elif isinstance(spec_option, (str, bytes)):
        ext = spec_option
    if ext and not ext.startswith("."):
        ext = "." + ext
    files = []
    for directory in dirs:
        try:
            for fname in os.listdir(directory):
                if spec_option is None or not ext or fname.endswith(ext):
                    files.append(os.path.join(directory, fname))
        except OSError:
            continue
    return sorted(files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    file_list = set()
    # Normalise spec_option to a set of extensions
    extensions = set()
    if spec_option:
        if isinstance(spec_option, str):
            if spec_option.startswith('.'):
                extensions.add(spec_option)
            else:
                extensions.add('.' + spec_option)
        else:
            try:
                for ext in spec_option:
                    if isinstance(ext, str):
                        if ext.startswith('.'):
                            extensions.add(ext)
                        else:
                            extensions.add('.' + ext)
            except TypeError:
                # spec_option is not iterable, treat as single extension
                if isinstance(spec_option, str):
                    extensions.add('.' + spec_option if not spec_option.startswith('.') else spec_option)
    for dir_path in settings_dirs:
        if not os.path.isdir(dir_path):
            continue
        for fname in os.listdir(dir_path):
            full_path = os.path.join(dir_path, fname)
            if not os.path.isfile(full_path):
                continue
            if extensions:
                if os.path.splitext(fname)[1] in extensions:
                    file_list.add(full_path)
            else:
                file_list.add(full_path)
    return sorted(file_list)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    # Return a sorted list of fully qualified file names from the given directories
    file_list = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                # If spec_option is None, include all files; otherwise filter by extension
                if spec_option is None or fname.endswith(spec_option):
                    file_list.append(os.path.join(directory, fname))
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return sorted(file_list)

