def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _resolve(group):
        if isinstance(group, dict):
            if 'include' in group:
                inc_path = group.pop('include')
                inc_dict = self._load_parser_dict(inc_path)
                group.update(inc_dict)
            for k, v in list(group.items()):
                _resolve(v)
        elif isinstance(group, list):
            for item in group:
                _resolve(item)

    for key, val in list(parser_dict.items()):
        _resolve(val)

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Recursively merge included group dictionaries into the current ones.
    # This function assumes that each group dictionary may contain an
    # 'include' key whose value is a list of group names to merge.
    # The merge is shallow; nested dicts are merged by updating keys.
    # The result is that every group dictionary contains the
    # combined key/value pairs of itself and all included groups.
    rechecked = True
    while rechecked:
        rechecked = False
        for group_name, group_content in list(parser_dict.items()):
            if not isinstance(group_content, dict):
                continue
            includes = group_content.pop('include', None)
            if not includes:
                continue
            rechecked = True
            for inc_name in includes:
                inc_dict = parser_dict.get(inc_name)
                if not isinstance(inc_dict, dict):
                    continue
                for key, val in inc_dict.items():
                    if key in group_content and isinstance(group_content[key], dict) and isinstance(val, dict):
                        # Merge nested dictionaries
                        group_content[key].update(val)
                    else:
                        group_content[key] = val
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Repeatedly resolve include directives until none remain.
    while True:
        pending = False
        for group_name, group_dict in list(parser_dict.items()):
            if not isinstance(group_dict, dict):
                continue
            # Get the include directive, if present.
            include_items = group_dict.pop('include', None)
            if not include_items:
                continue
            pending = True
            # Normalise to a list of group names.
            if isinstance(include_items, str):
                include_items = [include_items]
            for inc_name in include_items:
                inc_group = parser_dict.get(inc_name)
                if inc_group is None:
                    raise KeyError(
                        f"{group_name!r} includes missing group {inc_name!r}"
                    )
                if not isinstance(inc_group, dict):
                    continue
                # Merge the included group's definitions into the current group.
                for key, value in inc_group.items():
                    if key not in group_dict:
                        group_dict[key] = value
        if not pending:
            break

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    import json
    import os

    def _load_json(path):
        with open(path, 'r') as f:
            return json.load(f)

    # Work on a copy of keys to avoid modification during iteration
    for key in list(parser_dict.keys()):
        val = parser_dict[key]
        if isinstance(val, dict) and 'include' in val:
            include_path = val.pop('include')
            # Resolve relative paths relative to the current spec file if available
            if hasattr(self, 'spec_file_path'):
                base_dir = os.path.dirname(self.spec_file_path)
                include_path = os.path.normpath(os.path.join(base_dir, include_path))
            included_data = _load_json(include_path)
            # Merge included data into the current dictionary
            for subkey, subval in included_data.items():
                if subkey in val:
                    # If both are dicts, merge recursively
                    if isinstance(val[subkey], dict) and isinstance(subval, dict):
                        val[subkey] = {**val[subkey], **subval}
                    else:
                        val[subkey] = subval
                else:
                    val[subkey] = subval
            # Recursively resolve includes inside the merged dict
            if isinstance(val, dict):
                self._include_groups(val)
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    if hasattr(self, "build_defaults"):
        defaults = self.build_defaults()
    if hasattr(self, "spec"):
        spec = self.spec
        if isinstance(spec, dict):
            defaults.update(spec)
        else:
            for name in dir(spec):
                if name.startswith("_"):
                    continue
                value = getattr(spec, name)
                if not callable(value):
                    defaults[name] = value
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue
        # Try to get value from spec; fall back to the option's default
        if hasattr(self, 'spec') and arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]
        elif not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        else:
            defaults[arg.name] = None
    return defaults

