    defaults = {}
    # Ensure the spec object exists and provides a `get` API
    if not hasattr(self, "spec"):
        return defaults

    for arg in self.args:
        # Try to fetch a value from the spec first
        if hasattr(self.spec, "get"):
            try:
                val = self.spec.get(arg.name)
                if val is not None:
                    defaults[arg.name] = val
                    continue
            except Exception:
                # If the spec lookup fails, fall back to the default
                pass

        # Fallback to the argument's own default if set
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    if not hasattr(self, "spec"):
        return defaults
    for arg in self.spec.args:
        if not isinstance(arg, _BaseOpt):
            continue
        # Add the default for the option if it is set
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        # Handle nested dict options by resolving their defaults recursively
        if isinstance(arg, DictOption) and arg.scheme:
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested
    return defaults

