def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Determine where option specifications are stored in the instance.
        # Common attribute names are used; feel free to adjust to your own code base.
        if hasattr(self, "parser_option_specs"):
            specs_mapping = self.parser_option_specs
        elif hasattr(self, "command_option_specs"):
            specs_mapping = self.command_option_specs
        elif hasattr(self, "options_by_command"):
            specs_mapping = self.options_by_command
        else:
            raise AttributeError(
                "No option specification mapping found on the instance. "
                "Expected one of 'parser_option_specs', 'command_option_specs', "
                "'options_by_command'."
            )

        # Retrieve the specs for the requested command.
        if command_name not in specs_mapping:
            raise ValueError(
                f"Unknown command name '{command_name}'. Available commands: "
                f"{sorted(specs_mapping)}"
            )

        options = specs_mapping[command_name]
        # If the stored value is not already a list, try to coerce it.
        if not isinstance(options, list):
            try:
                options = list(options)
            except TypeError:
                raise TypeError(
                    f"Options for command '{command_name}' are not iterable and "
                    "cannot be converted to a list."
                )
        return options

