def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Define keywords that indicate a secret or sensitive argument
    SINCE_KEYWORDS = ('password', 'token', 'secret', 'key', 'pwd')
    silent_args = []

    # Try to get the argument dictionary
    try:
        arg_dict = vars(args)
    except Exception:
        # Fallback: if args is a dict, use it directly
        if isinstance(args, dict):
            arg_dict = args
        else:
            # We cannot introspect the arguments; return empty list
            return silent_args

    for key, value in arg_dict.items():
        if any(keyword in key.lower() for keyword in SINCE_KEYWORDS):
            silent_args.append(key)

    return silent_args

