def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched = []
    for opt in options_spec:
        condition = opt.get('required_when')
        if not condition:
            continue
        # If condition is a string, evaluate it in a safe context
        if isinstance(condition, str):
            try:
                if eval(condition, {}, {'args': args, 'command_name': command_name}):
                    matched.append(opt['name'])
                    continue
            except Exception:
                # ignore any errors in evaluating the condition
                pass
        # If condition is callable, call it with command_name and args
        if callable(condition):
            try:
                if condition(command_name, args):
                    matched.append(opt['name'])
                    continue
            except Exception:
                pass
        # If condition is a dict, check for expected keys
        if isinstance(condition, dict):
            try:
                # Example: {'command_name': 'foo'} or similar
                if condition.get('command_name') == command_name:
                    matched.append(opt['name'])
                    continue
            except Exception:
                pass
    return matched

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []

    # Normalise args to a mapping if possible
    args_map = args if isinstance(args, dict) else {}
    # If args is an iterable of arg names, keep as iterable
    args_iter = args if isinstance(args, (list, tuple, set)) else []

    for opt in options_spec:
        # Expect option to be a mapping
        if not isinstance(opt, dict):
            continue

        opt_name = opt.get('arg')
        if not opt_name:
            continue

        cond = opt.get('required_when')
        if not cond:
            continue

        matched = False

        # Function that decides match
        if callable(cond):
            try:
                matched = bool(cond(command_name, args_map, args_iter))
            except Exception:
                matched = False

        # Dictionary condition: evaluate key/value pairs
        elif isinstance(cond, dict):
            matched = True
            for key, value in cond.items():
                if key == 'command':
                    if isinstance(value, (list, tuple, set)):
                        if command_name not in value:
                            matched = False
                            break
                    else:
                        if command_name != value:
                            matched = False
                            break
                elif key in ('arg', 'args'):
                    if isinstance(value, (list, tuple, set)):
                        if not any(v in args_iter or v in args_map for v in value):
                            matched = False
                            break
                    else:
                        if value not in args_iter and value not in args_map:
                            matched = False
                            break
                else:
                    # Default to checking in mapping of args
                    if not isinstance(args_map, dict):
                        matched = False
                        break
                    if args_map.get(key) != value:
                        matched = False
                        break

        # Truthy value treated as a condition that must be True
        elif cond:
            matched = True

        if matched:
            required.append(opt_name)

    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
