        if matched:
            arg_name = spec.get('arg') or spec.get('dest') or spec.get('name')
            if arg_name is not None:
                required.append(arg_name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Iterate over all supplied arguments
    for argname, argattrs in args.items():
        # Skip if the argument value is not a mapping
        if not isinstance(argattrs, dict):
            continue

        # Retrieve the length limit; defaults to None if not provided
        length = argattrs.get("length")
        if length is None:
            continue

        # Ensure there is a value to compare
        value = argattrs.get("value")
        if value is None:
            continue

        # Perform the length check
        try:
            if len(value) > length:
                abort(
                    f"Argument {argname} has length {len(value)} "
                    f"which exceeds the allowed maximum of {length}"
                )
        except TypeError:
            abort(
                f"Argument {argname} has a value that does not support "
                "len() for length validation"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Argument specifications are expected to be stored in self.parsed_yaml under the key 'args'
    arg_specs = self.parsed_yaml.get('args', {})

    # Helper to validate a single argument's length
    def _check_length(name, value, spec):
        # Determine the maximum allowed length, using 'length' or 'max_length' keys if present
        max_len = spec.get('length')
        if max_len is None:
            max_len = spec.get('max_length')
        if max_len is None:
            return  # No length restriction specified

        # Only strings, sequences, and mappings have a concrete length
        if not isinstance(value, (str, list, tuple, dict)):
            raise TypeError(f"Argument '{name}' must be a string, list, tuple, or dict to validate length, got {type(value).__name__}")

        try:
            val_len = len(value)
        except TypeError:
            raise TypeError(f"Cannot compute length of argument '{name}' of type {type(value).__name__}")

        if val_len > max_len:
            raise ValueError(f"Argument '{name}' length {val_len} exceeds maximum allowed {max_len}")

    # Normalize and validate based on the type of 'args' provided
    if isinstance(args, list):
        for arg_item in args:
            if not isinstance(arg_item, dict):
                raise TypeError("Each positional argument must be represented as a dict")
            if len(arg_item) != 1:
                raise ValueError("Each positional argument dict must contain exactly one key")
            name, value = next(iter(arg_item.items()))
            spec = arg_specs.get(name, {})
            _check_length(name, value, spec)
    else:  # Assume mapping of argument names to values
        for name, value in args.items():
            spec = arg_specs.get(name, {})
            _check_length(name, value, spec)

