def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Ensure we have a mapping of valid choices for each argument.
        if not hasattr(self, "choices"):
            # No choices defined; nothing to validate.
            return

        for arg_name, value in args.items():
            # Only validate arguments that have a predefined set of choices.
            if arg_name not in self.choices:
                continue

            valid_choices = self.choices[arg_name]

            # If the choice list is a mapping, use its keys as valid choices.
            if isinstance(valid_choices, dict):
                valid_choices = list(valid_choices.keys())

            if value not in valid_choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Expected one of {valid_choices!r}."
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions (assumed to be stored in parsed_yaml)
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        # Skip validation for arguments that are not defined or have no choice list
        arg_def = arg_defs.get(arg_name)
        if not arg_def:
            continue
        # If the definition itself is a dict, look for 'choices'
        if isinstance(arg_def, dict):
            choices = arg_def.get('choices')
        else:
            # If the definition is a list or tuple, take the first element's dict
            if isinstance(arg_def, (list, tuple)) and arg_def:
                choices = arg_def[0].get('choices')
            else:
                choices = None
        if not choices:
            continue
        # Normalize the provided value: allow single value or iterable of values
        if isinstance(value, (list, tuple)):
            for v in value:
                if v not in choices:
                    abort(
                        f"Argument `{arg_name}` has invalid value "
                        f"'{v}'. Allowed choices are: {choices}"
                    )
        else:
            if value not in choices:
                abort(
                    f"Argument `{arg_name}` has invalid value "
                    f"'{value}'. Allowed choices are: {choices}"
                )

def validate_choices_args(self, args):
