    if isinstance(arg_spec, list):
        # Convert list of single-key dicts to a mapping of arg name -> attrs
        spec_dict = {}
        for item in arg_spec:
            self._assert_command_dict(item, '[list-item]', ['args'])
            key, attrs = list(item.items())[0]
            spec_dict[key] = attrs
