            continue  # Skip unknown argument definitions
        # Only run choice validation if 'choices' are defined
        if 'choices' in attrs:
            choices = attrs['choices']
            if not isinstance(choices, (list, tuple, set)):
                self._abort(f"Argument '{arg_name}': 'choices' must be a list/tuple/set")
            if arg_value not in choices:
                self._abort(
                    f"Invalid value for argument '{arg_name}': {arg_value} "
                    f"not among allowed choices {choices}"
                )

def validate_choices_args(self, args):
