    items = []
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, list):
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                items.append((item[0], item[1]))

    # Validate each choice argument against its allowed choices
    for arg_name, value in items:
        # Retrieve the specification for this argument
        spec = None
        if isinstance(arg_specs, dict):
            spec = arg_specs.get(arg_name)
        elif isinstance(arg_specs, list):
            for entry in arg_specs:
                if isinstance(entry, dict) and arg_name in entry:
                    spec = entry[arg_name]
                    break

        if not spec:
            continue

        # If the spec defines a 'choices' field, ensure the value is allowed
        if isinstance(spec, dict):
            choices = spec.get("choices")
            if choices and value not in choices:
                abort(
                    "Invalid value for choice argument '%s': '%s' not in %s"
                    % (arg_name, value, ", ".join(map(str, choices)))
                )

def validate_choices_args(self, args):
        """
        Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # self.choices should be a mapping of argument name to an iterable of allowed values
        choices_map = getattr(self, 'choices', {})
        for arg_name, arg_val in args.items():
            if arg_name not in choices_map:
                # not a choice argument; skip
                continue

            allowed = choices_map[arg_name]
            if not isinstance(allowed, (list, tuple, set)):
                # treat as single value
                allowed = {allowed}

            # allow a single value or a list/tuple of values
            if isinstance(arg_val, (list, tuple)):
                invalid_vals = [v for v in arg_val if v not in allowed]
                if invalid_vals:
                    msg = (
                        f"Invalid value(s) {invalid_vals} for argument "
                        f"'{arg_name}'. Expected one of {sorted(allowed)}."
                    )
                    raise ValueError(msg)
            else:
                if arg_val not in allowed:
                    msg = (
                        f"Invalid value '{arg_val}' for argument "
                        f"'{arg_name}'. Expected one of {sorted(allowed)}."
                    )
                    raise ValueError(msg)

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: A mapping of argument names to dictionaries containing
                 ``value`` and optionally ``min`` and ``max``, or a list of
                 tuples in the form (value, min, max).
    """
    # support dict-based specification
    if isinstance(args, dict):
        for name, cfg in args.items():
            if not isinstance(cfg, dict):
                continue
            if 'value' not in cfg:
                continue
            val = cfg['value']
            min_val = cfg.get('min')
            max_val = cfg.get('max')
            if min_val is not None and val < min_val:
                raise ValueError(
                    f"Argument '{name}' with value {val} is less than minimum {min_val}"
                )
            if max_val is not None and val > max_val:
                raise ValueError(
                    f"Argument '{name}' with value {val} is greater than maximum {max_val}"
                )
    # support list/tuple-based specification
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) >= 3:
                val, min_val, max_val = item[0], item[1], item[2]
                if min_val is not None and val < min_val:
                    raise ValueError(
                        f"Value {val} is less than minimum {min_val}"
                    )
                if max_val is not None and val > max_val:
                    raise ValueError(
                        f"Value {val} is greater than maximum {max_val}"
                    )
    else:
        raise TypeError(
            "args must be a dict or a list/tuple containing value-min-max tuples"
        )
    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :return: ``args`` if all values are within bounds.
    :raise ValueError: If a value is outside the specified bounds or bounds are not set.
    """
    # Retrieve optional bounds from the instance attributes
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)

    # Ensure at least one bound is defined
    if min_val is None and max_val is None:
        raise ValueError("Both minimum and maximum bounds are undefined")

    # Iterate over the provided arguments and validate each one
    for value in args:
        if min_val is not None and value < min_val:
            raise ValueError(
                f"Argument {value!r} is less than the minimum allowed {min_val!r}"
            )
        if max_val is not None and value > max_val:
            raise ValueError(
                f"Argument {value!r} exceeds the maximum allowed {max_val!r}"
            )

    return args

def validate_min_max_args(self, args):
