def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a single
        ``(value, min, max)`` tuple, a list of such tuples, or a dict
        containing the keys ``value``, ``min`` and ``max``.
    """
    def _check(value, minimum, maximum):
        if minimum is not None and value < minimum:
            raise ValueError(
                f"value {value} is less than the minimum {minimum}"
            )
        if maximum is not None and value > maximum:
            raise ValueError(
                f"value {value} is greater than the maximum {maximum}"
            )

    # Helper to validate a single triad
    def _validate_triad(triad):
        if isinstance(triad, (list, tuple)):
            if len(triad) != 3:
                raise TypeError(
                    "expected (value, min, max) tuple, got length "
                    f"{len(triad)}"
                )
            value, minimum, maximum = triad
            _check(value, minimum, maximum)
        elif isinstance(triad, dict):
            if 'value' not in triad:
                raise KeyError("dict must contain a 'value' key")
            value = triad['value']
            minimum = triad.get('min')
            maximum = triad.get('max')
            _check(value, minimum, maximum)
        else:
            raise TypeError(
                f"invalid argument type {type(triad).__name__} for min/max check"
            )

    # Handle various possible shapes of args
    if isinstance(args, dict):
        # Single argument using dict form
        _validate_triad(args)
    elif isinstance(args, (list, tuple)):
        # Sequence of triads or nested dicts
        for item in args:
            _validate_triad(item)
    else:
        # Assume a single triad
        _validate_triad(args)

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(self, "min") or not hasattr(self, "max"):
        raise AttributeError("`min` and `max` attributes must be defined on the instance before validation.")
    min_val, max_val = self.min, self.max
    for idx, val in enumerate(args):
        if val < min_val or val > max_val:
            raise ValueError(
                f"Argument at position {idx} ({val}) is out of allowed range "
                f"[{min_val}, {max_val}]."
            )

def create_complex_argument_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    import argparse
    spec_option = spec_option or {}

    class ComplexArgumentType:
        """Argument type that parses key=value pairs into a dictionary."""

        def __init__(self, spec):
            self.spec = spec

        def __call__(self, value):
            if not value:
                parsed = {}
            else:
                parsed = {}
                for token in value.split(','):
                    if '=' not in token:
                        raise argparse.ArgumentTypeError(
                            f"Invalid value for {option_name!r}: "
                            f"'{token}'. Expected 'key=value'."
                        )
                    key, val = token.split('=', 1)
                    parsed[key.strip()] = val.strip()

            # Validate required keys if specified
            required_keys = self.spec.get('required', [])
            missing = [k for k in required_keys if k not in parsed]
            if missing:
                raise argparse.ArgumentTypeError(
                    f"Missing required key(s) {missing!r} for "
                    f"{option_name!r}."
                )
            return parsed

    return ComplexArgumentType(spec_option)

