def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    # Determine verbosity level
    if verbose is None:
        verbosity = "-v"
    else:
        verbosity = f"-{verbose}"
    # Use logger verbosity if available
    try:
        verbosity = "-vvvvv" if ir_plugin.logger.isEnabledFor(logging.DEBUG) else verbosity
    except Exception:
        pass  # ignore if logger or logging not configured

    # Build the base command
    command = ["ansible-playbook", verbosity]

    # Add any additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(f"--{key}")
                # if False, skip
            else:
                command.append(f"--{key}")
                command.append(str(value))

    # Add extra variables if provided
    if extra_vars:
        # Convert dict to key=value pairs or JSON string
        try:
            import json
            var_str = json.dumps(extra_vars)
            command.extend(["--extra-vars", var_str])
        except Exception:
            # Fallback to simple key=value spacing
            command.extend(["--extra-vars",
                            " ".join(f"{k}={v}" for k, v in extra_vars.items())])

    # Append the playbook path
    command.append(playbook_path)

    # Execute the command
    ir_plugin.logger.debug("Executing ansible-playbook: %s", " ".join(command))
    try:
        p = subprocess.Popen(
            command,
            cwd=ir_workspace.root if hasattr(ir_workspace, "root") else None,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        out, err = p.communicate()
        if p.returncode != 0:
            raise RuntimeError(
                f"Ansible playbook failed (rc={p.returncode}): {err.decode(errors='ignore')}"
            )
        return out.decode(errors="ignore")
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, val in values_dict.items():
        if isinstance(val, str):
            v = val.strip()
            # Boolean conversion
            if v.lower() in ("true", "false"):
                values_dict[key] = v.lower() == "true"
            # Integer conversion
            elif v.isdigit() or (v.startswith('-') and v[1:].isdigit()):
                values_dict[key] = int(v)
            # Float conversion
            else:
                try:
                    values_dict[key] = float(v)
                except ValueError:
                    values_dict[key] = val
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Retrieve a mapping of argument names to conversion callables specific
        # to the given parser.  The mapping is expected to be stored on the
        # instance as a dictionary called ``_converters`` where the first level
        # key is the parser name and the second level key is the argument name.
        # If no mapping is found we simply leave the values untouched.
        converters = getattr(self, "_converters", {}).get(parser_name, {})

        for arg, conversion in converters.items():
            # Skip if argument is not present or already None
            if arg not in values_dict or values_dict[arg] is None:
                continue

            value = values_dict[arg]
            try:
                # Handle the most common scalar types explicitly to give
                # predictable boolean, list, and numeric conversions.
                if conversion is bool:
                    if isinstance(value, str):
                        values_dict[arg] = value.lower() in ("true", "1", "yes", "on")
                    else:
                        values_dict[arg] = bool(value)
                elif conversion is int:
                    values_dict[arg] = int(value)
                elif conversion is float:
                    values_dict[arg] = float(value)
                elif conversion is list:
                    if isinstance(value, str):
                        values_dict[arg] = [
                            item.strip() for item in value.split(",") if item.strip()
                        ]
                    else:
                        values_dict[arg] = list(value)
                else:
                    # Assume a user supplied callable that returns the desired type.
                    values_dict[arg] = conversion(value)
            except Exception:
                # If conversion fails we keep the original value to avoid
                # discarding user supplied data. In a real implementation
                # logging could be added here.
                pass
        # The method mutates values_dict in place; nothing is returned. """

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        if value is None:
            continue
        if isinstance(value, str):
            val = value.strip()
            if not val:
                continue
            lower_val = val.lower()
            if lower_val in ("true", "false"):
                values_dict[key] = lower_val == "true"
                continue
            try:
                int_val = int(val)
                values_dict[key] = int_val
                continue
            except ValueError:
                pass
            try:
                float_val = float(val)
                values_dict[key] = float_val
                continue
            except ValueError:
                pass
            if "," in val:
                values_dict[key] = [item.strip() for item in val.split(",")]
                continue
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json
    # Try to locate a JSON spec file; fall back to YAML if JSON not found
    spec_file = None
    for name in ('plugin.json', 'spec.json', 'manifest.json'):
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_file = candidate
            break
    if spec_file is None:
        # Try YAML file
        try:
            import yaml
        except ImportError:
            raise FileNotFoundError("No plugin spec file found in '{}'".format(plugin_dir))
        for name in ('plugin.yaml', 'spec.yaml', 'manifest.yaml'):
            candidate = os.path.join(plugin_dir, name)
            if os.path.isfile(candidate):
                spec_file = candidate
                break
        if spec_file is None:
            raise FileNotFoundError("No plugin spec file found in '{}'".format(plugin_dir))
    # Load spec
    if spec_file.endswith('.json'):
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec_dict = json.load(f)
    else:
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec_dict = yaml.safe_load(f)
    # Flatten dictionary
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items
    return _flatten(spec_dict)

